/** All translations for zizhitongjian ch.024 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "起強圉協洽，盡昭陽赤奮若，凡七年。", literal: "From Qianggu Xiehe through Zhaoyang Chifenruo; seven years in all.", idiomatic: "From Qianggu Xiehe through Zhaoyang Chifenruo—seven years in all." },
  { zh: "1春，二月，詔減口賦錢什三。", literal: "1. In spring, the second month, an edict reduced the poll tax by three-tenths.", idiomatic: "1. In spring, the second month, an edict cut the poll tax by thirty percent." },
  { zh: "----2夏，四月，癸未，帝崩於未央宮；", literal: "----2 In summer, the fourth month, on guiwei, the emperor died at Weiyang Palace;", idiomatic: "----2 In summer, the fourth month, on guiwei, the emperor died at Weiyang Palace;" },
  { zh: "無嗣。", literal: "he left no heir.", idiomatic: "he left no heir." },
  { zh: "時武帝子獨有廣陵王胥，大將軍光與群臣議所立，咸持廣陵王。", literal: "At that time among Emperor Wu's sons only the Prince of Guangling, Xu, remained; Grand General Guang and the ministers debated whom to establish, and all favored the Prince of Guangling.", idiomatic: "At that time Emperor Wu's only surviving son was Prince Xu of Guangling; Grand General Guang and the ministers debated whom to enthrone, and all favored the Prince of Guangling." },
  { zh: "王本以行失道，先帝所不用；", literal: "The prince had long since lost the Way in his conduct and had been passed over by the former emperor;", idiomatic: "The prince had long since lost the Way in his conduct and had been passed over by the former emperor;" },
  { zh: "光內不自安。", literal: "Guang inwardly was ill at ease.", idiomatic: "Guang was inwardly ill at ease." },
  { zh: "朗有上書言：「周太王廢太伯立王季，文王捨伯邑考立武王，唯在所宜，雖廢長立少可也。", literal: "A gentleman of the Lang submitted a memorial, saying: \"King Tai of Zhou set aside Taibo and established Wang Ji; King Wen set aside Boyi Kao and established King Wu—only fitness matters; though one abolishes the elder to establish the younger, it may be done.", idiomatic: "A gentleman of the Lang submitted a memorial: \"King Tai of Zhou set aside Taibo and established Wang Ji; King Wen set aside Boyi Kao and established King Wu—only fitness matters; abolishing the elder to establish the younger can be right." },
  { zh: "廣陵王不可以承宗廟。", literal: "The Prince of Guangling cannot undertake the ancestral temple.", idiomatic: "The Prince of Guangling cannot undertake the ancestral temple." },
  { zh: "」言合光意。", literal: "\" The words accorded with Guang's intent.", idiomatic: "\" The words accorded with Guang's intent." },
  { zh: "光以其書示丞相敞等，擢郎為九江太守。", literal: "Guang showed the memorial to Chancellor Chang and the others and promoted the gentleman to Governor of Jiujiang.", idiomatic: "Guang showed the memorial to Chancellor Chang and the others and promoted the gentleman to Governor of Jiujiang." },
  { zh: "即日承皇后詔，遣行大鴻臚事少府樂成、宗正德、光祿大夫吉、中郎將利漢，迎昌邑王賀，乘七乘傳詣長安邸。", literal: "That same day, acting on the empress dowager's edict, he sent the Acting Grand Herald, Director of the Palace Treasury Yuecheng, Director of the Imperial Clan De, Palace Grandee Ji, and Palace Cadet General Li Han to welcome the Prince of Changyi, He, who traveled by seven-relay post carriage to the Chang'an residence.", idiomatic: "That same day, acting on the empress dowager's edict, he sent Acting Grand Herald Yuecheng, Director of the Imperial Clan De, Palace Grandee Ji, and Palace Cadet General Li Han to welcome Prince He of Changyi, who traveled by seven-relay post carriage to the Chang'an residence." },
  { zh: "光又白皇后，徒右將軍安世為車騎將軍。", literal: "Guang also reported to the empress dowager and transferred Right General Anshi to General of Chariots and Cavalry.", idiomatic: "Guang also reported to the empress dowager and transferred Right General Anshi to General of Chariots and Cavalry." },
  { zh: "賀，昌邑哀王之子也，在國素狂縱，動作無節。", literal: "He was son of King Ai of Changyi and in his domain had always been wild and unrestrained, his conduct without measure.", idiomatic: "He was the son of King Ai of Changyi and in his domain had always been wild and unrestrained, his conduct without measure." },
  { zh: "武帝之喪，賀遊獵不止。", literal: "During Emperor Wu's mourning, He did not cease hunting and roaming.", idiomatic: "During Emperor Wu's mourning, He never stopped hunting and roaming." },
  { zh: "嘗遊方與，不半日馳二百里。", literal: "Once while touring Fangyu he galloped two hundred li in less than half a day.", idiomatic: "Once while touring Fangyu he galloped two hundred li in less than half a day." },
  { zh: "中尉琅邪王吉上疏諫曰：「大王不好書術而樂逸游，馮式撙銜，馳騁不止，口倦虖叱吒，手苦於棰轡，身勞虖車輿，朝則冒霧露，晝則被塵埃，夏則為大暑之所暴炙，冬則為風寒之所匽薄，數以耎脆之玉體犯勤勞之煩毒，非所以全壽命之宗也，又非所以進仁義之隆也。", literal: "Commandant Wang Ji of Langye submitted a memorial of admonition, saying: \"Your Highness does not love books and arts but delights in roaming at ease, gripping the reins in driving posture and galloping without cease—your mouth weary from shouting and roaring, your hands tormented by whip and bridle, your body worn by carriage and chariot; in the morning you meet mist and dew, by day you are clothed in dust; in summer you are scorched by great heat, in winter you are pelted by wind and cold. Repeatedly you set this tender, fragile jade body against toilsome harm—not the way to preserve the root of long life, nor the way to advance the height of benevolence and righteousness.", idiomatic: "Commandant Wang Ji of Langye submitted a memorial of admonition: \"Your Highness does not love books and the arts but delights in roaming at ease—gripping the reins, galloping without cease. Your mouth grows weary from shouting; your hands ache from whip and bridle; your body is worn by carriage and chariot. In the morning you meet mist and dew; by day you are clothed in dust; in summer you are scorched by great heat; in winter you are pelted by wind and cold. Again and again you set this tender, fragile body against toilsome harm—not the way to preserve long life, nor to advance benevolence and righteousness.\"" },
  { zh: "夫廣廈之下，細旃之上，明師居前，勤誦在後，上論唐、虞之際，下及殷、周之盛，考仁聖之風，習治國之道，訢訢焉發憤忘食，日新厥德，其樂豈銜橛之間哉！", literal: "Under a broad hall, upon fine felt, with an enlightened teacher before you and diligent recitation behind, discoursing above on the age of Tang and Yu and reaching below to the splendor of Yin and Zhou, examining the winds of benevolence and sagehood and practicing the Way of governing the state—eagerly forgetting food in ardent study, renewing your virtue day by day—would its joy be merely between bit and curb!", idiomatic: "Under a broad hall, upon fine felt, with an enlightened teacher before you and diligent recitation behind—discoursing on the age of Tang and Yu, reaching down to the splendor of Yin and Zhou, examining the winds of benevolence and sagehood, practicing the Way of governing the state—eagerly forgetting food in ardent study, renewing your virtue day by day—would its joy be merely between bit and curb!\"" },
  { zh: "休則俛仰屈伸以利形，進退步趨以實下，吸新吐故以練臧，專意積精以適神，於以養生，豈不長哉！", literal: "In rest, bend and stretch to benefit the form; advance and retreat, step and pace to strengthen the lower body; draw in the new and expel the old to train the viscera; focus the mind and gather essence to suit the spirit—in this way to nourish life, is it not long-lasting!", idiomatic: "In rest, bend and stretch to benefit the form; advance and retreat, step and pace to strengthen the lower body; draw in the new and expel the old to train the viscera; focus the mind and gather essence to suit the spirit—in this way to nourish life, is it not lasting!\"" },
  { zh: "大王誠留意如此，則心有堯、舜之志，體有喬、松之壽，美聲廣譽，登而上聞，則福祿其臻而社稷安矣。", literal: "If Your Highness truly heed this, then your heart will hold the intent of Yao and Shun, your body the longevity of Qiao and Song, fine renown and broad praise mounting to reach those above, and fortune and emolument will arrive while the altars of soil and grain are secure.", idiomatic: "If Your Highness truly heed this, your heart will hold the intent of Yao and Shun, your body the longevity of Qiao and Song; fine renown will mount to those above, fortune will arrive, and the altars of soil and grain will be secure.\"" },
  { zh: "皇帝仁聖，至今思慕未怠，於宮館、囿池、戈獵之樂未有所幸，大王宜夙夜念此以承聖意。", literal: "The emperor was benevolent and sage; to this day his mourning has not slackened. He never indulged in the pleasures of palaces, parks, ponds, arms, or hunting. Your Highness ought day and night to keep this in mind to carry out his intent.", idiomatic: "The emperor was benevolent and sage; to this day his mourning has not slackened. He never indulged in palaces, parks, ponds, arms, or hunting. Your Highness ought day and night to keep this in mind and carry out his intent.\"" },
  { zh: "諸侯骨肉，莫親大王，大王於屬則子也，於位則臣也，一身而二任之責加焉。", literal: "Among the feudal lords in flesh and bone, none is closer than Your Highness. In kinship you are a son; in station you are a subject—upon one person the double burden of both offices is laid.", idiomatic: "Among the feudal lords in flesh and bone, none is closer than Your Highness. In kinship you are a son; in station you are a subject—upon one person the double burden of both offices is laid.\"" },
  { zh: "恩愛行義，孅介有不具者，於以上聞，非饗國之福也。", literal: "If in affection, conduct, or the slightest propriety anything is lacking and it reaches those above, it is not the blessing of a state that enjoys offerings.", idiomatic: "If in affection, conduct, or the slightest propriety anything is lacking and it reaches those above, it is not the blessing of a state that enjoys offerings.\"" },
  { zh: "」王乃下令曰：「寡人造行不能無惰，中尉其忠，數輔吾過。", literal: "\" The prince thereupon issued an order: \"My conduct cannot be without sloth; the Commandant is loyal and repeatedly assists my faults.", idiomatic: "\" The prince issued an order: \"My conduct cannot be without sloth; the Commandant is loyal and repeatedly corrects my faults.\"" },
  { zh: "」使謁者千秋賜中尉牛肉五百斤，酒五石，脯五束。", literal: "\" He sent the Usher Qianqiu to bestow on the Commandant five hundred jin of beef, five piculs of wine, and five bundles of dried meat.", idiomatic: "\" He sent Usher Qianqiu to bestow on the Commandant five hundred jin of beef, five piculs of wine, and five bundles of dried meat." },
  { zh: "其後復放縱自若。", literal: "Afterward he again gave himself to wild license as before.", idiomatic: "Afterward he again gave himself to wild license as before." },
  { zh: "郎中令山陽龔遂，忠厚剛毅，有大節，內諫爭於王，外責傅相，引經義，陳禍福，至於涕泣，蹇蹇亡已，面刺王過。", literal: "Director of the Gentlemen Gong Sui of Shanyang was loyal, thick, firm, and resolute, with great integrity; inwardly he remonstrated with the prince, outwardly he held the tutor and chancellor to account, citing canonical principles and laying out fortune and calamity until he wept, steadfast and unceasing, confronting the prince's faults to his face.", idiomatic: "Director of the Gentlemen Gong Sui of Shanyang was loyal, steadfast, and resolute, with great integrity; inwardly he remonstrated with the prince, outwardly he held the tutor and chancellor to account, citing canonical principles and laying out fortune and calamity until he wept—steadfast and unceasing, confronting the prince's faults to his face." },
  { zh: "王至掩耳起走，曰：「郎中令善愧人！", literal: "The prince would cover his ears, rise, and flee, saying: \"The Director of the Gentlemen is skilled at shaming people!", idiomatic: "The prince would cover his ears, rise, and flee, saying, \"The Director of the Gentlemen is skilled at shaming people!\"" },
  { zh: "」王嘗久與騶奴、宰人遊戲飲食，賞賜無度，遂入見王，涕泣膝行，左右侍御皆出涕。", literal: "\" Once the prince spent long days gaming, eating, and drinking with grooms, slaves, and cooks, bestowing rewards without measure. Sui entered to see the prince, weeping and advancing on his knees; attendants left and right all shed tears.", idiomatic: "\" Once the prince spent long days gaming, eating, and drinking with grooms, slaves, and cooks, bestowing rewards without measure. Sui entered to see the prince, weeping and advancing on his knees; attendants left and right all shed tears." },
  { zh: "王曰：「郎中令何為哭？", literal: "The prince said: \"Director of the Gentlemen, why do you weep?", idiomatic: "The prince said, \"Director of the Gentlemen, why do you weep?\"" },
  { zh: "」遂曰：「臣痛社稷危也！", literal: "\" Sui said: \"Your servant grieves that the altars of soil and grain are in peril!", idiomatic: "\" Sui said, \"Your servant grieves that the altars of soil and grain are in peril!\"" },
  { zh: "願賜清閒，竭愚！", literal: "I beg leave for a quiet audience to exhaust my foolishness!", idiomatic: "I beg a quiet audience to exhaust my foolish counsel!\"" },
  { zh: "」王辟左右。", literal: "\" The prince dismissed those at his side.", idiomatic: "\" The prince dismissed those at his side." },
  { zh: "遂曰：「大王知膠西王所以為無道亡乎？", literal: "Sui said: \"Does Your Highness know why the Prince of Jiaoxi became lawless and perished?", idiomatic: "Sui said, \"Does Your Highness know why the Prince of Jiaoxi became lawless and perished?\"" },
  { zh: "」王曰：「不知也。", literal: "\" The prince said: \"I do not know.", idiomatic: "\" The prince said, \"I do not know.\"" },
  { zh: "」曰：「臣聞膠西王有諛臣侯得，王所為擬於桀、紂也，得以為堯、舜也。", literal: "\" He said: \"Your servant has heard that the Prince of Jiaoxi had a flatterer, Hou De; what the prince did resembled Jie and Zhou, yet De called it Yao and Shun.", idiomatic: "\" He said, \"Your servant has heard that the Prince of Jiaoxi had a flatterer, Hou De; what the prince did resembled Jie and Zhou, yet De called it Yao and Shun.\"" },
  { zh: "王說其諂諛，常與寢處，唯得所言，以至於是。", literal: "The prince delighted in his flattery, constantly shared bed and dwelling with him, and heeded only what De said—until it came to this.", idiomatic: "The prince delighted in his flattery, constantly shared bed and dwelling with him, and heeded only what De said—until it came to this.\"" },
  { zh: "今大王親近群小，漸漬邪惡所習，存亡之機，不可不慎也！", literal: "Now Your Highness draws near petty men, steeped in what evil habits instill—the hinge of survival and extinction cannot be treated lightly!", idiomatic: "Now Your Highness draws near petty men, steeped in what evil habits instill—the hinge of survival and extinction cannot be treated lightly!\"" },
  { zh: "臣請選郎通經有行義者與王起成，坐則誦《詩》、《書》，立則習禮容，宜有益。", literal: "Your servant asks to select gentlemen of the Lang who know the classics and possess conduct and righteousness to rise and sit with Your Highness—when seated to recite the Odes and Documents, when standing to practice ritual deportment; it should be of benefit.", idiomatic: "Your servant asks to select gentlemen of the Lang who know the classics and possess conduct and righteousness to rise and sit with Your Highness—when seated to recite the Odes and Documents, when standing to practice ritual deportment; it should help.\"" },
  { zh: "」王許之。", literal: "\" The prince assented.", idiomatic: "\" The prince assented." },
  { zh: "遂乃選郎中張安等十人侍王。", literal: "Sui thereupon selected Palace Gentlemen Zhang An and nine others to attend the prince.", idiomatic: "Sui selected Palace Gentlemen Zhang An and nine others to attend the prince." },
  { zh: "居數日，王皆逐去安等。", literal: "Within several days the prince drove out An and the rest.", idiomatic: "Within several days the prince drove out An and the rest." },
  { zh: "王嘗見大白犬，頸以下似人，冠方山冠而無尾，以問龔遂，遂曰：「此天戒，言在側者盡冠狗也，去之則存，不去則亡矣。", literal: "The prince once saw a great white dog, from the neck down like a man, wearing a fangshan cap but without a tail. He asked Gong Sui; Sui said: \"This is a heaven-sent warning, saying those at your side are all capped dogs; remove them and you survive—fail to remove them and you perish.", idiomatic: "The prince once saw a great white dog, from the neck down like a man, wearing a fangshan cap but without a tail. He asked Gong Sui; Sui said, \"This is a heaven-sent warning: those at your side are all capped dogs; remove them and you survive—fail to remove them and you perish.\"" },
  { zh: "」後又聞人聲曰：「熊！", literal: "\" Later he again heard a human voice say: \"Bear!", idiomatic: "\" Later he again heard a human voice say, \"Bear!\"" },
  { zh: "」視而見大熊，左右莫見，以問遂，遂曰：「熊，山野之獸，而來入宮室，王獨見之，此天戒大王，恐宮室將空，危亡象也。", literal: "\" He looked and saw a great bear; those left and right saw nothing. He asked Sui; Sui said: \"The bear is a beast of mountain and wild, yet it came into the palace chambers and Your Highness alone saw it. This is heaven's warning to Your Highness: I fear the chambers will be emptied—the image of peril and extinction.", idiomatic: "\" He looked and saw a great bear; those left and right saw nothing. He asked Sui; Sui said, \"The bear is a beast of mountain and wild, yet it came into the palace chambers and Your Highness alone saw it. This is heaven's warning: I fear the chambers will be emptied—the image of peril and extinction.\"" },
  { zh: "」王仰天而歎曰：「不祥何為數來！", literal: "\" The prince looked up to heaven and sighed: \"Why do ill omens come again and again!", idiomatic: "\" The prince looked up to heaven and sighed, \"Why do ill omens come again and again!\"" },
  { zh: "」遂叩頭曰：「臣不敢隱忠，數言危亡之戒；", literal: "\" Sui knocked his head on the ground and said: \"Your servant dares not conceal loyalty; I have repeatedly spoken warnings of peril and extinction;", idiomatic: "\" Sui knocked his head on the ground and said, \"Your servant dares not conceal loyalty; I have repeatedly spoken warnings of peril and extinction;\"" },
  { zh: "大王不說。", literal: "Your Highness is not pleased.", idiomatic: "Your Highness is not pleased.\"" },
  { zh: "夫國之存亡，豈在臣言哉！", literal: "Whether the state survives or perishes—how could it depend on your servant's words!", idiomatic: "Whether the state survives or perishes—how could it depend on my words!\"" },
  { zh: "願王內自揆度。", literal: "I beg Your Highness inwardly to measure and reflect.", idiomatic: "I beg Your Highness inwardly to measure and reflect.\"" },
  { zh: "大王誦《詩》三百五篇，人事浹，王道備。", literal: "Your Highness recites the three hundred and five pieces of the Odes—human affairs are thorough, the kingly Way complete.", idiomatic: "Your Highness recites the three hundred and five pieces of the Odes—human affairs are thorough, the kingly Way complete.\"" },
  { zh: "王之所行，中《詩》一篇何等也？", literal: "In what Your Highness does, which single piece of the Odes does it match?", idiomatic: "In what Your Highness does, which single piece of the Odes does it match?\"" },
  { zh: "大王位於諸侯王，行污於庶人，以存難，以亡易，宜深察之！", literal: "Your Highness stands among feudal kings yet acts fouler than a commoner—to preserve is hard, to perish is easy; you ought to examine this deeply!", idiomatic: "Your Highness stands among feudal kings yet acts fouler than a commoner—to preserve is hard, to perish is easy; you ought to examine this deeply!\"" },
  { zh: "」後又血污王坐席，王問遂；", literal: "\" Later blood again stained the prince's seat; the prince asked Sui;", idiomatic: "\" Later blood again stained the prince's seat; the prince asked Sui;" },
  { zh: "遂叫然號曰：「宮空不久，妖祥數至。", literal: "Sui cried out in a shout: \"The chambers will soon be empty; prodigies and omens arrive in succession.", idiomatic: "Sui cried out: \"The chambers will soon be empty; prodigies and omens arrive in succession.\"" },
  { zh: "血者，陰憂象也，宜畏慎自省！", literal: "Blood is the image of yin sorrow; you ought to fear, be cautious, and examine yourself!", idiomatic: "Blood is the image of yin sorrow; you ought to fear, be cautious, and examine yourself!\"" },
  { zh: "」王終不改節。", literal: "\" The prince in the end did not change his ways.", idiomatic: "\" The prince in the end did not change his ways." },
  { zh: "及徵書至，夜漏未盡一刻，以火發書。", literal: "When the summons arrived, before one quarter of the night watch had passed he opened the letter by firelight.", idiomatic: "When the summons arrived, before one quarter of the night watch had passed he opened the letter by firelight." },
  { zh: "其日中，王發；", literal: "At midday the prince set out;", idiomatic: "At midday the prince set out;" },
  { zh: "晡時，至定陶，行百三十五里，侍從者馬死相望於道。", literal: "at the hour of shen he reached Dingtao, having traveled one hundred thirty-five li; among his attendants horses died one after another along the road.", idiomatic: "at the hour of shen he reached Dingtao, having traveled one hundred thirty-five li; among his attendants horses died one after another along the road." },
  { zh: "王吉奏書戒王曰：「臣聞高宗諒闇，三年不言。", literal: "Wang Ji submitted a memorial warning the prince: \"Your servant has heard that Gaozong observed deep mourning and for three years did not speak.", idiomatic: "Wang Ji submitted a memorial warning the prince: \"Your servant has heard that Gaozong observed deep mourning and for three years did not speak.\"" },
  { zh: "今大王以喪事徵，宜日夜哭泣悲哀而已，慎毋有所發！", literal: "Now Your Highness is summoned for the mourning rites; you ought only to weep and grieve day and night—take care to initiate nothing!", idiomatic: "Now Your Highness is summoned for the mourning rites; you ought only to weep and grieve day and night—take care to initiate nothing!\"" },
  { zh: "大將軍仁愛、勇智、忠信之德，天下莫不聞；", literal: "The Grand General's virtues of benevolence, love, courage, wisdom, loyalty, and trustworthiness—none under Heaven has not heard of them;", idiomatic: "The Grand General's virtues of benevolence, courage, wisdom, loyalty, and trustworthiness—none under Heaven has not heard of them;\"" },
  { zh: "事孝武皇帝二十餘年，未嘗有過。", literal: "he served Emperor Xiao of Wu for more than twenty years and never once had a fault.", idiomatic: "he served Emperor Xiao of Wu for more than twenty years without a single fault.\"" },
  { zh: "先帝棄群臣，屬以天下，寄幼孤焉。", literal: "The former emperor left his ministers, entrusted him with all under Heaven, and placed the young orphan in his care.", idiomatic: "The former emperor left his ministers, entrusted him with all under Heaven, and placed the young orphan in his care.\"" },
  { zh: "大將軍抱持幼君襁褓之中，布政施教，海內晏然，雖周公、伊尹無以加也。", literal: "The Grand General held the young lord from swaddling clothes, spread government and taught the people, and within the seas all was tranquil—even the Duke of Zhou and Yi Yin could not surpass him.", idiomatic: "The Grand General held the young lord from swaddling clothes, spread government and taught the people, and within the seas all was tranquil—even the Duke of Zhou and Yi Yin could not surpass him.\"" },
  { zh: "今帝崩無嗣，大將軍惟思可以奉宗廟者，攀援而立大王，其仁厚豈有量哉！", literal: "Now the emperor has died without an heir; the Grand General has pondered only who can serve the ancestral temple, and drawing support has established Your Highness—how can his benevolence and depth be measured!", idiomatic: "Now the emperor has died without an heir; the Grand General has pondered only who can serve the ancestral temple and, drawing support, has established Your Highness—how can his benevolence and depth be measured!\"" },
  { zh: "臣願大王事之，敬之，政事壹聽之，大王垂拱南面而已。", literal: "Your servant wishes Your Highness to serve him, revere him, and in all government affairs heed him entirely—Your Highness need only sit with folded hands facing south.", idiomatic: "Your servant wishes Your Highness to serve him, revere him, and in all government affairs heed him entirely—Your Highness need only sit with folded hands facing south.\"" },
  { zh: "願留意，常以為念！", literal: "I beg you to keep this in mind and often make it your thought!", idiomatic: "Keep this in mind and often make it your thought!\"" },
  { zh: "王至濟陽，求長鳴雞，道買積竹杖。", literal: "The prince reached Jiyang, sought long-crowing cocks, and along the road bought tall bamboo staffs.", idiomatic: "The prince reached Jiyang, sought long-crowing cocks, and along the road bought tall bamboo staffs." },
  { zh: "過弘農，使大奴善以衣車載女子。", literal: "Passing Hongnong, he had his great slave Shan use a curtained carriage to carry women.", idiomatic: "Passing Hongnong, he had his great slave Shan use a curtained carriage to carry women." },
  { zh: "至湖，使者以讓相安樂。", literal: "Reaching Hu, the envoy reproached Chancellor Anle.", idiomatic: "Reaching Hu, the envoy reproached Chancellor Anle." },
  { zh: "安樂告龔遂，遂入問王，王曰：「無有。", literal: "Anle told Gong Sui; Sui entered and questioned the prince. The prince said: \"There was nothing.", idiomatic: "Anle told Gong Sui; Sui entered and questioned the prince. The prince said, \"There was nothing.\"" },
  { zh: "」遂曰：「即無有，何愛一善以毀行義！", literal: "\" Sui said: \"If there was nothing, why spare one Shan and ruin righteous conduct!", idiomatic: "\" Sui said, \"If there was nothing, why spare one Shan and ruin righteous conduct!\"" },
  { zh: "請收屬吏，以湔灑大王。", literal: "I ask to take him into custody and hand him to the officials, to cleanse Your Highness.", idiomatic: "I ask to take him into custody and hand him to the officials, to cleanse Your Highness.\"" },
  { zh: "」即捽善屬衛士長行法。", literal: "\" He at once seized Shan and handed him to the captain of the guards for punishment according to law.", idiomatic: "\" He at once seized Shan and handed him to the captain of the guards for punishment according to law." },
  { zh: "王到霸上，大鴻臚郊迎，騶奉乘輿車。", literal: "When the prince reached Bashang, the Grand Herald met him in suburban welcome; grooms presented the imperial carriage.", idiomatic: "When the prince reached Bashang, the Grand Herald met him in suburban welcome; grooms presented the imperial carriage." },
  { zh: "王使壽成御，郎中令遂參乘。", literal: "The prince had Shoucheng drive; the Director of the Gentlemen Sui rode as attendant.", idiomatic: "The prince had Shoucheng drive; Director of the Gentlemen Sui rode as attendant." },
  { zh: "且至廣明、東都門，遂曰：「禮，奔喪望見國都哭。", literal: "As they neared Guangming and the East Capital Gate, Sui said: \"By ritual, when hurrying to a funeral one weeps on sight of the capital.", idiomatic: "As they neared Guangming and the East Capital Gate, Sui said, \"By ritual, when hurrying to a funeral one weeps on sight of the capital.\"" },
  { zh: "此長安東郭門也。", literal: "This is the eastern outer gate of Chang'an.", idiomatic: "This is the eastern outer gate of Chang'an.\"" },
  { zh: "」王曰：「我嗌痛，不能哭。", literal: "\" The prince said: \"My throat hurts; I cannot weep.", idiomatic: "\" The prince said, \"My throat hurts; I cannot weep.\"" },
  { zh: "」至城門，遂復言，王曰：「城門與郭門等耳。", literal: "\" Reaching the city gate, Sui spoke again; the prince said: \"The city gate and the outer gate are the same.", idiomatic: "\" Reaching the city gate, Sui spoke again; the prince said, \"The city gate and the outer gate are the same.\"" },
  { zh: "」且至未央宮東闕，遂曰：「昌邑帳在是闕外馳道北，未至帳所，有南北行道，馬足未至數步；", literal: "\" As they neared the eastern tower of Weiyang Palace, Sui said: \"The Changyi quarters lie north of the imperial roadway outside this tower. Before reaching the quarters there is a north-south lane; when the horse's hooves are still several paces short;", idiomatic: "\" As they neared the eastern tower of Weiyang Palace, Sui said, \"The Changyi quarters lie north of the imperial roadway outside this tower. Before reaching the quarters there is a north-south lane; when the horse's hooves are still several paces short;\"" },
  { zh: "大王宜下車，鄉闕西面伏哭，盡哀止。", literal: "Your Highness ought to descend from the carriage, turn toward the tower and prostrate yourself weeping to the west, exhausting grief and then stopping.", idiomatic: "Your Highness ought to descend, turn toward the tower and prostrate yourself weeping to the west, exhaust your grief, and then stop.\"" },
  { zh: "」王曰：「諾。", literal: "\" The prince said: \"Yes.", idiomatic: "\" The prince said, \"Yes.\"" },
  { zh: "」到，哭如儀。", literal: "\" On arrival he wept according to ritual.", idiomatic: "\" On arrival he wept according to ritual." },
  { zh: "六月，丙寅，王受皇帝璽綬，襲尊號，尊皇后曰皇太后。", literal: "In the sixth month, on bingyin, the prince received the imperial seal and ribbon, assumed the exalted title, and honored the empress as empress dowager.", idiomatic: "In the sixth month, on bingyin, the prince received the imperial seal and ribbon, assumed the exalted title, and honored the empress as empress dowager." },
  { zh: "----3壬申，葬孝昭皇帝於平陵。", literal: "----3 On renshen, Emperor Xiao of Zhao was buried at Pingling.", idiomatic: "----3 On renshen, Emperor Xiao of Zhao was buried at Pingling." },
  { zh: "----4昌邑王既立，淫戲無度。", literal: "----4 Once the Prince of Changyi was established, his lewd sport knew no bounds.", idiomatic: "----4 Once Prince He of Changyi was established, his lewd sport knew no bounds." },
  { zh: "昌邑官屬皆徵至長安，往往超擢拜官。", literal: "Changyi officials and retainers were all summoned to Chang'an and were often promoted and enfeoffed beyond their rank.", idiomatic: "Changyi officials and retainers were all summoned to Chang'an and were often promoted and enfeoffed beyond their rank." },
  { zh: "相安樂遷長樂衛尉。", literal: "Chancellor Anle was transferred to Commandant of the Guards for Changle.", idiomatic: "Chancellor Anle was transferred to Commandant of the Guards for Changle." },
  { zh: "龔遂見安樂，流涕謂曰：「王立為天子，日益驕溢，諫之不復聽。", literal: "Gong Sui saw Anle, wept, and said: \"The prince has been made Son of Heaven and daily grows more arrogant and excessive; he no longer heeds admonition.", idiomatic: "Gong Sui saw Anle, wept, and said, \"The prince has been made Son of Heaven and daily grows more arrogant and excessive; he no longer heeds admonition.\"" },
  { zh: "今哀痛未盡，日與近臣飲酒作樂，鬥虎豹，召皮軒車九旒，驅馳東西，所為悖道。", literal: "Now mourning grief is not yet exhausted, yet day by day he drinks and makes sport with close retainers, pits tigers and leopards in combat, summons the nine-tassel leather-canopied chariot, and gallops east and west—his acts violate the Way.", idiomatic: "Mourning grief is not yet exhausted, yet day by day he drinks and makes sport with close retainers, pits tigers and leopards in combat, summons the nine-tassel leather-canopied chariot, and gallops east and west—his acts violate the Way.\"" },
  { zh: "古制寬，大臣有隱退；", literal: "Ancient institutions were broad; great ministers might withdraw in concealment;", idiomatic: "Ancient institutions were broad; great ministers might withdraw in concealment;\"" },
  { zh: "今去不得，陽狂恐知，身死為世戮，奈何？", literal: "now to leave is not permitted; feigning madness for fear of being known, one's body dies and becomes the world's disgrace—what is to be done?", idiomatic: "now to leave is not permitted; feigning madness for fear of being known, one's body dies and becomes the world's disgrace—what is to be done?\"" },
  { zh: "君，陛下故相，宜極諫爭。", literal: "You, my lord, were the emperor's former chancellor; you ought to remonstrate to the utmost.", idiomatic: "You, my lord, were the emperor's former chancellor; you ought to remonstrate to the utmost.\"" },
  { zh: "王夢青蠅之矢積西階東，可五六石，以屋版瓦覆之，以問遂，遂曰：「陛下之《詩》不雲乎：『營營青蠅，止於籓。", literal: "The emperor dreamed that green fly droppings piled east of the western stair, some five or six piculs, covered with roof tiles; he asked Sui. Sui said: \"Does not Your Majesty's Odes say: 'Buzzing green flies stop at the fence.", idiomatic: "The emperor dreamed that green fly droppings piled east of the western stair, some five or six piculs, covered with roof tiles; he asked Sui. Sui said, \"Does not Your Majesty's Odes say, 'Buzzing green flies stop at the fence.\"" },
  { zh: "愷悌君子，毋信讒言。", literal: "Easy and gracious is the gentleman—do not trust slanderous words.", idiomatic: "Easy and gracious is the gentleman—do not trust slanderous words.\"" },
  { zh: "』陛下左側讒人眾多，如是青蠅惡矣。", literal: "' Slanderers at Your Majesty's left are many; such are the green flies' evil.", idiomatic: "' Slanderers at Your Majesty's left are many—such is the evil of green flies.\"" },
  { zh: "宜進先帝大臣子孫，親近以為左右。", literal: "You ought to advance the sons and grandsons of the former emperor's great ministers and draw them near as those at your side.", idiomatic: "You ought to advance the sons and grandsons of the former emperor's great ministers and draw them near as those at your side.\"" },
  { zh: "如不忍昌邑故人，信用讒諛，必有凶咎。", literal: "If you cannot bear to part with old Changyi associates and trust slander and flattery, there will surely be misfortune and calamity.", idiomatic: "If you cannot bear to part with your old Changyi associates and trust slander and flattery, disaster is sure to follow." },
  { zh: "願詭禍為福，皆放逐之！", literal: "I wish to turn misfortune into fortune—all should be banished!", idiomatic: "Turn misfortune into fortune—banish them all!" },
  { zh: "臣當先逐矣。", literal: "Your servant ought to be the first expelled.", idiomatic: "I ought to be the first one expelled." },
  { zh: "」王不聽。", literal: "\" The king would not listen.", idiomatic: "\" The king would not listen." },
  { zh: "太僕丞河東張敞上書諫，曰：「孝昭皇帝蚤崩無嗣，大臣憂懼，選賢聖承宗廟，東迎之日，唯恐屬車之行遲。", literal: "Director of Studs Assistant Zhang Chang of Hedong submitted a memorial remonstrating, saying: \"Emperor Xiao of filial piety died early without heir; great ministers were anxious and fearful, selected the worthy and sage to succeed the ancestral temple. On the day of welcoming from the east, all feared the train of the imperial carriage would be delayed.", idiomatic: "Director of Studs Assistant Zhang Chang of Hedong submitted a memorial of remonstrance, saying, \"Emperor Zhao died young without an heir; the great ministers were anxious and fearful and selected a worthy man to succeed the ancestral temple. On the day of welcoming him from the east, everyone feared the imperial procession would be delayed." },
  { zh: "今天子以盛年初即位，天下莫不拭目傾耳，觀化聽風。", literal: "Now the Son of Heaven at a flourishing age has first taken the throne; all under Heaven none do not wipe their eyes and incline their ears, observing transformation and listening to the wind.", idiomatic: "Now the emperor has just taken the throne in the prime of youth, and all under Heaven watches with eager eyes and ears for signs of reform." },
  { zh: "國輔大臣未褒，而昌邑小輩先遷，此過之大者也。", literal: "State-supporting great ministers have not yet been rewarded, yet Changyi petty men are promoted first—this is among the greatest of faults.", idiomatic: "The great ministers who support the state have not yet been rewarded, while petty men from Changyi are promoted first—this is a grave fault indeed." },
  { zh: "」王不聽。", literal: "\" The king would not listen.", idiomatic: "\" The king would not listen." },
  { zh: "大將軍光憂懣，獨以問所親故吏大司農田延年。", literal: "Grand General Guang was distressed and resentful and alone took counsel with his close old subordinate Grand Minister of Agriculture Tian Yannian.", idiomatic: "Grand General Huo Guang was distressed and resentful and confided only in his close old subordinate, Grand Minister of Agriculture Tian Yannian." },
  { zh: "延年曰：「將軍為國柱石，審此人不可，何不建白太后，更選賢而立之？", literal: "Yannian said: \"The general is the state's pillar and cornerstone; having examined that this man will not do, why not present a memorial to the Empress Dowager, select again the worthy, and establish him?", idiomatic: "Yannian said, \"General, you are the pillar of the state. Having judged this man unfit, why not report to the Empress Dowager, choose another worthy man, and enthrone him?" },
  { zh: "」光曰：「今欲如是，於古嘗有此不？", literal: "\" Guang said: \"If we now wish to act thus, was there ever such a thing in antiquity?\"", idiomatic: "\" Guang said, \"If we wish to act thus now, was there ever such a thing in antiquity?\"" },
  { zh: "」延年曰：「伊尹相殷，廢太甲以安宗廟，後世稱其忠。", literal: "\" Yannian said: \"Yi Yin served as minister of Yin, deposed Tai Jia to secure the ancestral temple, and later ages praised his loyalty.", idiomatic: "\" Yannian said, \"Yi Yin served Yin, deposed Tai Jia to secure the ancestral temple, and later ages praised his loyalty." },
  { zh: "將軍若能行此，亦漢之伊尹也。", literal: "If the general can carry this out, he too will be the Yi Yin of Han.", idiomatic: "If the general can do this, you will be Han's Yi Yin as well." },
  { zh: "」光乃引延年給事中，陰與車騎將軍張安世圖計。", literal: "\" Thereupon Guang brought Yannian in as Palace Attendant and secretly with Cavalry-and-Chariots General Zhang Anshi plotted the plan.", idiomatic: "\" Thereupon Guang brought Yannian in as Palace Attendant and secretly plotted with Cavalry-and-Chariots General Zhang Anshi." },
  { zh: "王出遊，光祿大夫魯國夏侯勝當乘輿前諫曰：「天久陰而不雨，臣下有謀上者。", literal: "The king went out touring; Palace Illustrious Grandee Xia Hou Sheng of Lu State, who should remonstrate before the imperial carriage, said: \"Heaven has long been overcast without rain—among the ministers below there are those plotting against their superior.", idiomatic: "When the king went out touring, Palace Illustrious Grandee Xia Hou Sheng of Lu, whose duty was to remonstrate before the imperial carriage, said, \"Heaven has long been overcast without rain—among the ministers below there are those plotting against their superior." },
  { zh: "陛下出，欲何之？", literal: "Your Majesty goes forth—whither do you wish to go?", idiomatic: "Your Majesty is going out—where do you intend to go?" },
  { zh: "」王怒，謂勝為示夭言，縛以屬吏。", literal: "\" The king was angry, called Sheng's words inauspicious speech, bound him, and handed him over to the officials.", idiomatic: "\" The king was angry, called Sheng's words inauspicious, bound him, and handed him over to the officials for punishment." },
  { zh: "吏白霍光，光不舉法。", literal: "The officials reported to Huo Guang; Guang did not enforce the law.", idiomatic: "The officials reported to Huo Guang, but Guang did not enforce the law." },
  { zh: "光讓安世，以為洩語。", literal: "Guang reproached Anshi, thinking he had leaked their words.", idiomatic: "Guang reproached Anshi, thinking he had leaked their plan." },
  { zh: "安世實不言；", literal: "Anshi in truth had not spoken;", idiomatic: "Anshi had in truth said nothing;" },
  { zh: "乃召問勝。", literal: "thereupon he summoned and questioned Sheng.", idiomatic: "so he summoned and questioned Sheng." },
  { zh: "勝對言：「在《鴻範傳》曰：『皇之不極，厥罰常陰，時則有下人伐上者。", literal: "Sheng replied, saying: \"In the Hong Fan Commentary it says: 'When the Sovereign lacks the utmost, its punishment is constant yin; at such times there are inferiors who attack their superior.", idiomatic: "Sheng replied, \"The Hong Fan Commentary says, 'When the Sovereign lacks the utmost, the punishment is constant overcast skies; at such times inferiors attack their superiors." },
  { zh: "』惡察察言，故云『臣下有謀』。", literal: "' I dislike overly explicit speech, therefore I said 'among the ministers below there is plotting.'\"", idiomatic: "' I dislike overly explicit speech, therefore I said 'among the ministers below there is plotting.'\"" },
  { zh: "」光、安世大驚，以此益重經術士。", literal: "\" Guang and Anshi were greatly alarmed and for this reason valued classicist scholars all the more.", idiomatic: "\" Guang and Anshi were greatly alarmed and for this reason valued classicist scholars all the more." },
  { zh: "侍中傅嘉數進諫，王亦縛嘉繫獄。", literal: "Palace Attendant Fu Jia repeatedly advanced remonstrance; the king also bound Jia and imprisoned him.", idiomatic: "Palace Attendant Fu Jia repeatedly remonstrated; the king also bound Jia and put him in prison." },
  { zh: "光、安世既定議，乃使田延年報丞相楊敞。", literal: "Once Guang and Anshi had settled their decision, they sent Tian Yannian to inform Chancellor Yang Chang.", idiomatic: "Once Guang and Anshi had settled their decision, they sent Tian Yannian to inform Chancellor Yang Chang." },
  { zh: "敞驚懼，不知所言，汗出洽背，徒唯唯而已。", literal: "Chang was alarmed and fearful, not knowing what to say; sweat poured soaking his back—he only murmured assent.", idiomatic: "Chang was alarmed and at a loss for words; sweat soaked his back and he could only murmur assent." },
  { zh: "延年起，至更衣，敞夫人遽從東廂謂敞曰：「此國大事，今大將軍議已定，使九卿來報君侯，君侯不疾應，與大將軍同心，猶與無決，先事誅矣！", literal: "Yannian rose and went to the side chamber; Chancellor Chang's wife hastily from the east wing said to Chang: \"This is a great affair of state. Now the Grand General's deliberation is settled and he sent the Nine Ministers to report to you, my lord. If you, my lord, do not respond swiftly and are of one heart with the Grand General, it is as if there were no resolution—you will be executed first!", idiomatic: "Yannian rose and went to the side chamber; Chancellor Chang's wife hastened from the east wing and said to him, \"This is a matter of state. The Grand General's plan is settled and he has sent the Nine Ministers to report to you. If you do not respond swiftly and stand with the Grand General, it is as good as having no resolution—you will be the first executed!" },
  { zh: "」延年從更衣還，敞夫人與延年參語許諾：「請奉大將軍教令！", literal: "\" When Yannian returned from the side chamber, Chancellor Chang's wife and Yannian spoke together in assent: \"We request to follow the Grand General's command!", idiomatic: "\" When Yannian returned from the side chamber, Chancellor Chang's wife and Yannian spoke together in assent, \"We shall follow the Grand General's command!" },
  { zh: "癸巳，光召丞相、御史、將軍、列侯、中二千石、大夫、博士會議未央宮。", literal: "On guisi, Guang summoned the chancellor, censor, generals, ranked marquises, officials of middle two thousand dan, grandees, and erudites to deliberate in Weiyang Palace.", idiomatic: "On guisi, Guang summoned the chancellor, censor, generals, ranked marquises, officials of middle two thousand dan rank, grandees, and erudites to meet in Weiyang Palace." },
  { zh: "光曰：「昌邑王行昏亂，恐危社稷，如何？", literal: "Guang said: \"The King of Changyi's conduct is benighted and chaotic—I fear he endangers the altars of soil and grain. What is to be done?\"", idiomatic: "Guang said, \"The King of Changyi's conduct is benighted and chaotic and I fear he endangers the state. What is to be done?\"" },
  { zh: "」群臣皆驚鄂失色，莫敢發言，但唯唯而已。", literal: "\" The assembled ministers were all startled speechless, faces changed color, none dared speak—they only murmured assent.", idiomatic: "\" The assembled ministers were all startled speechless, their faces drained of color; none dared speak and could only murmur assent." },
  { zh: "田延年前，離席按劍曰：「先帝屬將軍以幼孤，寄將軍以天下，以將軍忠賢，能安劉氏也。", literal: "Tian Yannian stepped forward, left his seat, and hand on sword said: \"The former emperor entrusted the general with the young orphan and committed all under Heaven to the general, because the general is loyal and worthy and can secure the house of Liu.", idiomatic: "Tian Yannian stepped forward, left his seat, and with hand on sword said, \"The late emperor entrusted you, General, with the young orphan and committed the realm to you because you are loyal and worthy and can secure the house of Liu." },
  { zh: "今群下鼎沸，社稷將傾；", literal: "Now the assembled ministers boil like a cauldron and the altars of soil and grain are about to topple;", idiomatic: "Now the court boils like a cauldron and the state is about to topple;" },
  { zh: "且漢之傳謚常為『孝』者，以長有天下，令宗廟血食也。", literal: "moreover among Han's transmitted posthumous titles those regularly bearing 'Filial' do so because they long held all under Heaven and let the ancestral temple receive blood sacrifice.", idiomatic: "moreover among Han's posthumous titles those bearing 'Filial' earned it by long holding the realm and keeping the ancestral sacrifices alive." },
  { zh: "如漢家絕祀，將軍雖死，何面目見先帝於地下乎？", literal: "If the house of Han's sacrifices are cut off, though the general die, with what face could he meet the former emperor below ground?", idiomatic: "If the house of Han's sacrifices end, General, even in death with what face could you meet the late emperor in the underworld?" },
  { zh: "今日之議，不得旋踵，群臣後應者，臣請劍斬之！", literal: "Today's deliberation brooks no turning of the heel; any minister who responds afterward—I request to cut him down with the sword!", idiomatic: "Today's deliberation brooks no delay; any minister who responds afterward—I ask to cut him down with the sword!" },
  { zh: "」光謝曰：「九卿責光是也！", literal: "\" Guang apologized, saying: \"The Nine Ministers rightly reproach Guang!", idiomatic: "\" Guang apologized, saying, \"The Nine Ministers rightly reproach me!" },
  { zh: "天下匈匈不安，光當受難。", literal: "All under Heaven is restive and unsettled; Guang ought to bear the hardship.", idiomatic: "All under Heaven is restless and unsettled; I ought to bear the hardship." },
  { zh: "」於是議者皆叩頭曰：「萬姓之命，在於將軍，唯大將軍令！", literal: "\" Thereupon the deliberators all kowtowed, saying: \"The myriad people's lives rest on the general—we await only the Grand General's command!", idiomatic: "\" Thereupon all present kowtowed, saying, \"The lives of the myriad people rest on the General—we await only the Grand General's command!" },
  { zh: "光即與群臣俱見，白太后，具陳昌邑王不可以承宗廟狀。", literal: "Guang immediately together with the assembled ministers went to audience, reported to the Empress Dowager, and fully set forth the King of Changyi's condition unfit to succeed the ancestral temple.", idiomatic: "Guang immediately went with the assembled ministers to audience, reported to the Empress Dowager, and fully set forth why the King of Changyi could not succeed the ancestral temple." },
  { zh: "皇太后乃車駕幸未央承明殿，詔諸禁門毋內昌邑群臣。", literal: "The Empress Dowager thereupon took her carriage and visited Weiyang's Chengming Hall and edicted that at all forbidden gates none should admit Changyi ministers.", idiomatic: "The Empress Dowager thereupon took her carriage to Chengming Hall in Weiyang Palace and edicted that at all forbidden gates Changyi ministers were not to be admitted." },
  { zh: "王入朝太后還，乘輦欲歸溫室。", literal: "The king entered to attend the Empress Dowager and returned, mounted the palanquin, and wished to return to the Warm Apartment.", idiomatic: "The king had attended the Empress Dowager and returned, mounted his palanquin, and wished to return to the Warm Apartment." },
  { zh: "中黃門宦者各持門扇，王入，門閉，昌邑群臣不得入。", literal: "Central Yellow Gate eunuchs each held the gate leaves; the king entered, the gates closed, and Changyi ministers could not enter.", idiomatic: "Central Yellow Gate eunuchs each held the gate panels; when the king entered the gates closed and the Changyi ministers could not follow." },
  { zh: "王曰：「何為？", literal: "The king said: \"What is this for?\"", idiomatic: "The king said, \"What is going on?\"" },
  { zh: "」大將軍跪曰：「有皇太后詔，毋內昌邑群臣！", literal: "\" The Grand General knelt and said: \"There is an edict of the Empress Dowager—do not admit Changyi ministers!\"", idiomatic: "\" The Grand General knelt and said, \"There is an edict of the Empress Dowager—do not admit the Changyi ministers!\"" },
  { zh: "」王曰：「徐之，何乃驚人如是！", literal: "\" The king said: \"Take it slowly—why startle people so!\"", idiomatic: "\" The king said, \"Take it slowly—why startle people like this!\"" },
  { zh: "」光使盡驅出昌邑群臣，置金馬門外。", literal: "\" Guang had all Changyi ministers driven out and placed outside the Golden Horse Gate.", idiomatic: "\" Guang had all the Changyi ministers driven out and placed outside the Golden Horse Gate." },
  { zh: "車騎將軍安世將羽林騎，收縛二百餘人，皆送廷尉詔獄。", literal: "Cavalry-and-Chariots General Anshi led Feathered Forest cavalry, seized and bound more than two hundred men, and all were sent to the Commandant of Justice's imperial prison.", idiomatic: "Cavalry-and-Chariots General Anshi led Feathered Forest cavalry, seized and bound more than two hundred men, and sent them all to the imperial prison under the Commandant of Justice." },
  { zh: "令故昭帝侍中中臣侍守王。", literal: "He ordered the former Emperor Zhao's palace attendants and inner attendants to attend and guard the king.", idiomatic: "He ordered Emperor Zhao's former palace attendants and inner attendants to attend and guard the king." },
  { zh: "光敕左右：「謹宿衛！", literal: "Guang charged those at hand: \"Guard carefully!", idiomatic: "Guang charged those at hand, \"Guard carefully!" },
  { zh: "卒有物故自裁，令我負天下，有殺主名。", literal: "If he should suddenly die by suicide, it would make me bear guilt under Heaven and have the reputation of regicide.", idiomatic: "If he should suddenly die by suicide, I would bear guilt under Heaven and have the name of regicide." },
  { zh: "」王尚未自知當廢，謂左右：「我故群臣從官安得罪，而大將軍盡系之乎！", literal: "\" The king did not yet know himself about to be deposed and said to those at hand: \"How have my old ministers and followers offended, that the Grand General binds them all!\"", idiomatic: "\" The king did not yet know he was about to be deposed and said to those at hand, \"How have my old ministers and followers offended that the Grand General binds them all!\"" },
  { zh: "頃之，有太后詔召王。", literal: "Before long there was an edict of the Empress Dowager summoning the king.", idiomatic: "Before long came an edict of the Empress Dowager summoning the king." },
  { zh: "王聞召，意恐，乃曰：「我安得罪而召我哉！", literal: "The king heard the summons, his mind fearful, and said: \"How have I offended that I am summoned!\"", idiomatic: "Hearing the summons, the king grew fearful and said, \"How have I offended that I am summoned!\"" },
  { zh: "」太后被珠襦，盛服坐武帳中，侍御數百人皆持兵，期門武士陛戟陳列殿下，群臣以次上殿，召昌邑王伏前聽詔。", literal: "\" The Empress Dowager wore a pearl-lined jacket and full regalia, seated in the martial canopy; several hundred attendants all held weapons; Barrier Gate warriors with halberds on the steps arrayed below the hall; the assembled ministers in order ascended the hall—the King of Changyi was summoned to prostrate before and hear the edict.", idiomatic: "\" The Empress Dowager wore a pearl-lined jacket and full court dress, seated in the martial canopy; several hundred attendants all held weapons; Barrier Gate warriors with halberds on the steps lined the hall below; the assembled ministers ascended in order, and the King of Changyi was summoned to prostrate and hear the edict." },
  { zh: "光與群臣連名奏王，尚書令讀奏曰：「丞相臣敞等昧死言皇太后陛下：孝昭皇帝早棄天下，遣使徵昌邑王典喪，服斬衰，無悲哀之心，廢禮誼，居道上不素食，使從官略女子載衣車，內所居傳捨。", literal: "Guang together with the assembled ministers jointly memorialized the king; the Director of the Masters of Writing read the memorial, saying: \"Chancellor your servant Chang and others, risking death, speak to Her Majesty the Empress Dowager: Emperor Xiao early abandoned all under Heaven; envoys were sent to summon the King of Changyi to preside over the mourning. He wore hemp mourning with frayed edges yet had no heart of grief, discarded ritual and propriety, while on the road did not eat vegetarian mourning food, had followers abduct women into clothing carts, and brought them within the relay lodges where he lodged.", idiomatic: "Guang and the assembled ministers jointly memorialized the king; the Director of the Masters of Writing read the memorial, saying, \"Chancellor Yang Chang and others, risking death, address Her Majesty the Empress Dowager: Emperor Zhao died young; envoys were sent to summon the King of Changyi to preside over the mourning. He wore frayed-edge hemp mourning yet had no heart of grief, discarded ritual and propriety, ate no mourning vegetarian food on the road, had followers seize women into clothing carts, and brought them into the relay lodges where he stayed." },
  { zh: "始至謁見，立為皇太子，常私買雞豚以食。", literal: "When he first arrived for audience he was established as heir apparent, yet constantly in private bought chickens and pigs to eat.", idiomatic: "When he first arrived for audience he was made heir apparent, yet constantly bought chickens and pigs in private to eat." },
  { zh: "受皇帝信璽、行璽大行前，就次，發璽不封。", literal: "He received the emperor's credential seal and traveling seal before the Grand Procession, took his place, and opened the seals without resealing them.", idiomatic: "He received the emperor's credential seal and traveling seal before the Grand Procession, took his place, and opened the seals without resealing them." },
  { zh: "從官更持節引內昌邑從官、騶宰、官奴二百餘人，常與居禁闥內敖戲。", literal: "Followers again held staffs of office and led in more than two hundred Changyi followers, outrider stewards, and official slaves, who constantly dwelt with him inside the forbidden inner gates sporting and playing.", idiomatic: "Followers again held staffs of office and led in more than two hundred Changyi followers, outrider stewards, and official slaves, who constantly lived with him inside the forbidden inner gates sporting and playing." },
  { zh: "為書曰：『皇帝問侍中君卿：使中御府令高昌奉黃金千斤，賜君卿取十妻。", literal: "He made a letter saying: 'The emperor inquires of Palace Attendant Junqing: I order the Director of the Inner Palace Treasury Gao Chang to present a thousand jin of gold and bestow on Junqing permission to take ten wives.", idiomatic: "He wrote a letter saying, 'The emperor inquires of Palace Attendant Junqing: I order Director of the Inner Palace Treasury Gao Chang to present a thousand jin of gold and bestow on Junqing permission to take ten wives." },
  { zh: "』大行在前殿，發樂府樂器，引內昌邑樂人擊鼓，歌吹，作俳倡；", literal: "' Before the front hall of the Grand Procession he issued music-office instruments, led in Changyi musicians to beat drums, sing and blow pipes, and perform comic entertainers;", idiomatic: "' Before the front hall of the Grand Procession he issued music-office instruments, brought in Changyi musicians to beat drums, sing and play pipes, and perform comic entertainers;" },
  { zh: "召內泰壹、宗廟樂人，悉奏眾樂。", literal: "he summoned inner Grand Unity and ancestral-temple musicians and had them all perform the full music.", idiomatic: "he summoned inner Grand Unity and ancestral-temple musicians and had them all perform the full repertoire." },
  { zh: "駕法駕驅馳北宮、桂宮，弄彘鬥虎。", literal: "He drove the imperial regalia carriage racing through Northern Palace and Cassia Palace, sporting with pigs and fighting tigers.", idiomatic: "He drove the imperial regalia carriage racing through the Northern Palace and Cassia Palace, sporting with pigs and fighting tigers." },
  { zh: "召皇太后御小馬車，使官奴騎乘，遊戲掖庭中。", literal: "He summoned the Empress Dowager's small horse carriage, had official slaves mount and ride, and sported in the Rear Palace.", idiomatic: "He summoned the Empress Dowager's small horse carriage, had official slaves mount and ride it, and sported in the Rear Palace." },
  { zh: "與孝昭皇帝宮人蒙等淫亂，詔掖庭令：『敢洩言，要斬！", literal: "With Emperor Xiao's palace women Meng and the rest he committed lewd disorder and edicted the Rear Palace director: 'Whoever dares leak word—beheading at the waist!", idiomatic: "With Emperor Zhao's palace women Meng and the rest he committed lewd disorder and edicted the Rear Palace director, 'Whoever dares leak word shall be beheaded at the waist!" },
  { zh: "』……」太后曰：「止！", literal: "' ……\" The Empress Dowager said: \"Stop!\"", idiomatic: "' ……\" The Empress Dowager said, \"Stop!\"" },
  { zh: "為人臣子，當悖亂如是邪！", literal: "As a man's minister and son, ought he be so perverse and chaotic!", idiomatic: "As subject and son, ought he be so perverse and chaotic!" },
  { zh: "」王離席伏。", literal: "\" The king left his seat and prostrated himself.", idiomatic: "\" The king left his seat and prostrated himself." },
  { zh: "尚書令復讀曰：「……取諸侯王、列侯、二千石綬及墨綬、黃綬以並佩昌邑郎官者免奴。", literal: "The Director of the Masters of Writing again read: \"…… He took marquises of kingdoms, ranked marquises, and two-thousand-dan ribbons together with black and yellow ribbons and had them all worn together by Changyi gentlemen-at-attendance to free slaves.", idiomatic: "The Director of the Masters of Writing read again, \"…… He took the ribbons of kings, marquises, and two-thousand-dan officials together with black and yellow ribbons and had Changyi gentlemen-at-attendance wear them together to free slaves." },
  { zh: "發御府金錢、刀劍、玉器、采繒，賞賜所與遊戲者。", literal: "He issued imperial treasury gold and cash, swords, jade objects, and colored silks, bestowing them on those with whom he sported.", idiomatic: "He issued imperial treasury gold, cash, swords, jade objects, and colored silks and bestowed them on his playmates." },
  { zh: "與從官、官奴夜飲，湛沔於酒。", literal: "With followers and official slaves he drank by night, steeped to the brim in wine.", idiomatic: "With followers and official slaves he drank by night, steeped in wine." },
  { zh: "獨夜設九賓溫室，延見姊夫昌邑關內侯。", literal: "Alone at night he set out nine-guest reception in the Warm Apartment and extended audience to his brother-in-law, Marquis within the Passes of Changyi.", idiomatic: "Alone at night he held nine-guest reception in the Warm Apartment and received his brother-in-law, Marquis within the Passes of Changyi." },
  { zh: "祖宗廟祠未舉，為璽書，使使者持節以三太牢祠昌邑哀王園廟，稱『嗣子皇帝』。", literal: "Ancestral temple sacrifices had not yet been performed; he made a sealed letter and sent envoys holding staffs of office with triple grand sacrificial victims to sacrifice at the park temple of the Lamented King of Changyi, styling himself 'heir-son emperor.'", idiomatic: "Ancestral temple sacrifices had not yet been performed; he made a sealed letter and sent envoys with staffs of office and triple grand sacrificial victims to sacrifice at the park temple of the Lamented King of Changyi, styling himself 'heir-son emperor.'" },
  { zh: "受璽以來二十七日，使者旁午，持節詔諸官署徵發凡一千一百二十七事。", literal: "From receiving the seal to the present twenty-seven days, envoys crisscrossed, holding staffs of office to edict all offices for requisitions and issuances—in all one thousand one hundred twenty-seven matters.", idiomatic: "In the twenty-seven days since receiving the seal, envoys crisscrossed constantly, holding staffs of office to edict all offices for requisitions and issuances—in all one thousand one hundred twenty-seven matters." },
  { zh: "荒淫迷惑，失帝王禮誼，亂漢制度。", literal: "Dissolute, lewd, and deluded, he lost the Son of Heaven's ritual and propriety and threw Han's institutions into disorder.", idiomatic: "Dissolute, lewd, and deluded, he abandoned imperial ritual and propriety and threw Han institutions into disorder." },
  { zh: "臣敞等數進諫，不變更，日以益甚。", literal: "Your servants Chang and the rest repeatedly advanced remonstrance; he did not change, and daily it grew worse.", idiomatic: "We repeatedly remonstrated; he did not change, and daily grew worse." },
  { zh: "恐危社稷，天下不安。", literal: "We fear he endangers the altars of soil and grain and all under Heaven is unsettled.", idiomatic: "We fear he endangers the state and all under Heaven is unsettled." },
  { zh: "臣敞等謹與博士議，皆曰：『今陛下嗣孝昭皇帝後，行淫辟不軌。", literal: "Your servants Chang and the rest respectfully deliberated with the erudites; all said: 'Now Your Majesty succeeds Emperor Xiao and conducts lewd depravity not according to the norm.", idiomatic: "We respectfully deliberated with the erudites; all said, 'Now Your Majesty succeeds Emperor Zhao and conducts lewd depravity contrary to the norm." },
  { zh: "「五辟之屬，莫大不孝。", literal: "\" Among the five serious offenses, none is greater than unfilial conduct.", idiomatic: "\" Among the five serious offenses, none is greater than unfilial conduct." },
  { zh: "」周襄王不能事母，《春秋》曰：「天王出居於鄭，」由不孝出之，絕之於天下也。", literal: "\" King Xiang of Zhou could not serve his mother. The Spring and Autumn Annals says: 'The Son of Heaven went out to dwell at Zheng'—because of unfilial conduct he was sent out and cut off from all under Heaven.", idiomatic: "\" King Xiang of Zhou could not serve his mother. The Spring and Autumn Annals says, 'The Son of Heaven went out to dwell at Zheng'—because of unfilial conduct he was sent out and cut off from all under Heaven." },
  { zh: "宗廟重於君，陛下不可以承天序，奉祖宗廟，子萬姓，當廢！", literal: "The ancestral temple weighs heavier than the ruler; Your Majesty cannot succeed Heaven's succession, serve the ancestral temple, or be parent to the myriad people—you ought to be deposed!", idiomatic: "The ancestral temple weighs heavier than the ruler; Your Majesty cannot succeed Heaven's order, serve the ancestral temple, or be parent to the myriad people—you ought to be deposed!" },
  { zh: "』臣請有司以一太牢具告祠高廟。", literal: "' Your servants request the responsible offices to report the sacrifice to the High Temple with one grand sacrificial victim.", idiomatic: "' We request the responsible offices to report the sacrifice to the High Temple with one grand sacrificial victim." },
  { zh: "」皇太后詔曰：「可。", literal: "\" The Empress Dowager edicted: \"Approved.", idiomatic: "\" The Empress Dowager edicted, \"Approved." },
  { zh: "」光令王起，拜受詔，王曰：「聞『天下有爭臣七人，雖亡道不失天下。", literal: "\" Guang ordered the king to rise and bow to receive the edict; the king said: \"I have heard 'Under all under Heaven there are seven remonstrating ministers—even if without the Way one does not lose the realm.", idiomatic: "\" Guang ordered the king to rise and bow to receive the edict; the king said, \"I have heard, 'Under Heaven there are seven remonstrating ministers—even if without the Way one does not lose the realm." },
  { zh: "』」光曰：「皇太后詔廢，安得稱天子！", literal: "'\" Guang said: \"The Empress Dowager has edicted deposal—how can you style yourself Son of Heaven!\"", idiomatic: "'\" Guang said, \"The Empress Dowager has edicted your deposition—how can you still call yourself Son of Heaven!\"" },
  { zh: "」乃即持其手，解脫其璽組，奉上太后，扶王下殿，出金馬門，群臣隨送。", literal: "\" Thereupon he immediately took his hand, removed his seal cord, presented it up to the Empress Dowager, supported the king down from the hall, and went out the Golden Horse Gate—the assembled ministers followed in escort.", idiomatic: "\" Thereupon he immediately took the king's hand, removed his seal cord, presented it to the Empress Dowager, supported the king down from the hall, and went out the Golden Horse Gate with the assembled ministers following in escort." },
  { zh: "王西面拜曰：「愚戇，不任漢事！", literal: "The king faced west and bowed, saying: \"Stupid and blunt—I am not fit for Han's affairs!", idiomatic: "The king faced west and bowed, saying, \"Stupid and blunt—I am not fit for Han's affairs!" },
  { zh: "」起，就乘輿副車，大將軍光送至昌邑邸。", literal: "\" He rose, mounted the palanquin's escort carriage, and Grand General Guang escorted him to the Changyi residence.", idiomatic: "\" He rose, mounted the escort carriage of the palanquin, and Grand General Guang escorted him to the Changyi residence." },
  { zh: "光謝曰：「王行自絕於天，臣寧負王，不敢負社稷！", literal: "Guang apologized, saying: \"Your Majesty's conduct has cut itself off from Heaven; your servant would rather fail Your Majesty than fail the altars of soil and grain!", idiomatic: "Guang apologized, saying, \"Your Majesty's conduct has cut itself off from Heaven; I would rather fail you than fail the state!" },
  { zh: "願王自愛，臣長不復左右。", literal: "I wish Your Majesty to care for yourself; your servant will long not again be at your side.", idiomatic: "Take care of yourself, Your Majesty; I shall not again be at your side for long." },
  { zh: "」光涕泣而去。", literal: "\" Guang wept as he departed.", idiomatic: "\" Guang wept as he departed." },
  { zh: "群臣奏言：「古者廢放之人，屏於遠方，不及以政。", literal: "The assembled ministers memorialized, saying: \"In antiquity deposed persons were screened off in distant regions and did not reach to government.", idiomatic: "The assembled ministers memorialized, saying, \"In antiquity deposed persons were banished to distant regions and did not participate in government." },
  { zh: "請徙王賀漢中房陵縣。", literal: "We request to relocate King He to Fangling County in Hanzhong.", idiomatic: "We request to relocate King He to Fangling County in Hanzhong." },
  { zh: "」太后詔歸賀昌邑，賜湯沐邑二千戶，故王家財物皆與賀；", literal: "\" The Empress Dowager edicted to return He to Changyi, bestowed a bath-and-lodging fief of two thousand households, and all the former royal house's goods and property were given to He;", idiomatic: "\" The Empress Dowager edicted to return He to Changyi, bestowed a bath fief of two thousand households, and gave him all the former royal house's goods and property;" },
  { zh: "及哀王女四人，各賜湯沐邑千戶；", literal: "and the Lamented King's four daughters each were bestowed bath fiefs of a thousand households;", idiomatic: "and the Lamented King's four daughters each received bath fiefs of a thousand households;" },
  { zh: "國除，為山陽郡。", literal: "the kingdom was abolished and made Shanyang commandery.", idiomatic: "the kingdom was abolished and made Shanyang commandery." },
  { zh: "昌邑群臣坐在國時不舉奏王罪過，令漢朝不聞知，又不能輔道，陷王大惡，皆下獄，誅殺二百餘人。", literal: "Changyi ministers were convicted because while in the kingdom they did not memorialize the king's offenses and let the Han court not hear of them, and also could not assist and guide him, plunging the king into great wickedness—all were sent down to prison and more than two hundred were executed.", idiomatic: "The Changyi ministers were convicted because while in the kingdom they had not reported the king's offenses and let the Han court remain ignorant, and also failed to guide him, plunging the king into great wickedness—all were imprisoned and more than two hundred were executed." },
  { zh: "唯中尉吉、郎中令遂以忠直數諫正，得減死，髡為城旦。", literal: "Only Commandant Ji and Director of the Palace Secretariat Sui, for loyal uprightness and repeatedly remonstrating and correcting, obtained reduced sentence from death and were shaved and made dawn wall-builders.", idiomatic: "Only Commandant Ji and Director of the Palace Secretariat Sui, for loyal uprightness and repeated remonstrance and correction, escaped death, were shaved, and sentenced to dawn wall-building labor." },
  { zh: "師王式繫獄當死，治事使者責問曰：「師何以無諫書？", literal: "Teacher Wang Shi was imprisoned and liable to death; the investigating envoy reproached and questioned, saying: \"Teacher, why are there no remonstrance memorials?\"", idiomatic: "Teacher Wang Shi was imprisoned and liable to death; the investigating envoy questioned him, saying, \"Teacher, why are there no remonstrance memorials?\"" },
  { zh: "」式對曰：「臣以《詩》三百五篇朝夕授王，至於忠臣、孝子之篇，未嘗不為王反覆誦之也。", literal: "\" Shi replied: \"Your subject with the three hundred and five pieces of the Odes morning and evening instructs the king; as for the pieces on loyal ministers and filial sons, your subject has never failed to recite them repeatedly for the king.", idiomatic: "\" Shi replied, \"Your subject with the three hundred and five pieces of the Odes morning and evening instructs the king; as for the pieces on loyal ministers and filial sons, your subject has never failed to recite them repeatedly for the king." },
  { zh: "至於危亡失道之君，未嘗不流涕為王深陳之也。", literal: "As for lords who were in peril, lost the Way, and perished, your subject has never failed to shed tears and for the king deeply set them forth.", idiomatic: "As for rulers who were in peril, lost the Way, and perished, your subject has never failed to shed tears and set them forth at length for the king." },
  { zh: "臣以三百五篇諫，是以無諫書。", literal: "Your subject remonstrates with the three hundred and five pieces—therefore there is no remonstrance memorial.", idiomatic: "Your subject remonstrates with the three hundred and five pieces—therefore there is no remonstrance memorial." },
  { zh: "」使者以聞，亦得減死論。", literal: "\" The envoy reported it; he also received a reduced-death sentence.", idiomatic: "\" The envoy reported it; he also received a reduced-death sentence." },
  { zh: "霍光以群臣奏事東宮，太后省政，宜知經術，白令夏侯勝用《尚書》授太后，遷勝長信少府，賜爵關內侯。", literal: "Huo Guang, because the ministers presented affairs at the Eastern Palace and the empress dowager oversaw government, thought she should know the classics; he reported to have Xiahou Sheng use the Documents to instruct the empress dowager, moved Sheng to Chamberlain of Changxin, and granted the title Marquis within the Passes.", idiomatic: "Huo Guang, because the ministers presented affairs at the Eastern Palace and the empress dowager oversaw government, thought she should know the classics; he reported to have Xiahou Sheng use the Documents to instruct the empress dowager, moved Sheng to Chamberlain of Changxin, and granted the title Marquis within the Passes." },
  { zh: "----5初，衛太子納魯國史良娣，生子進，號史皇孫。", literal: "----5 At the beginning, the Heir of Wei took as consort Lady Shi, a worthy lady of Lu, and bore a son Jin, styled the Shi Imperial Grandson.", idiomatic: "----5 At the beginning, the Heir of Wei took as consort Lady Shi, a worthy lady of Lu, and bore a son Jin, styled the Shi Imperial Grandson." },
  { zh: "皇孫納涿郡王夫人，生子病已，號皇曾孫。", literal: "The imperial grandson took as consort the Lady of Wang of Zhuo commandery and bore a son Bingyi, styled the Imperial Great-Grandson.", idiomatic: "The imperial grandson took as consort the Lady of Wang of Zhuo commandery and bore a son Bingyi, styled the Imperial Great-Grandson." },
  { zh: "皇曾孫生數月，遭巫蠱事，太子三男、一女及諸妻、妾皆遇害，獨皇曾孫在，亦坐收系郡邸獄。", literal: "The imperial great-grandson was several months old when the witchcraft affair struck; the crown prince's three sons, one daughter, and all wives and concubines were harmed—only the imperial great-grandson remained, and he too was implicated, taken, and held in the commandery hostel prison.", idiomatic: "The imperial great-grandson was several months old when the witchcraft affair struck; the crown prince's three sons, one daughter, and all wives and concubines were harmed—only the imperial great-grandson remained, and he too was implicated, taken, and held in the commandery hostel prison." },
  { zh: "故廷尉監魯國丙吉受詔治巫蠱獄，吉心知太子無事實，重哀皇曾孫無辜，擇謹厚女徒謂城胡組、淮陽郭徵卿，令乳養曾孫，置閒燥處。", literal: "Former Commandant of Justice Supervisor Bing Ji of Lu received an edict to try the witchcraft prison; Ji in his heart knew the crown prince had no factual guilt and deeply pitied the imperial great-grandson's innocence; he chose careful, solid female convicts named Cheng Huzu and Guo Zhengqing of Huaiyang, ordered them to nurse the great-grandson, and placed him in a quiet, dry place.", idiomatic: "Former Commandant of Justice Supervisor Bing Ji of Lu received an edict to try the witchcraft prison; Ji in his heart knew the crown prince had no factual guilt and deeply pitied the imperial great-grandson's innocence; he chose careful, solid female convicts named Cheng Huzu and Guo Zhengqing of Huaiyang, ordered them to nurse the great-grandson, and placed him in a quiet, dry place." },
  { zh: "吉日再省視。", literal: "On auspicious days he again went to inspect.", idiomatic: "On auspicious days he again went to inspect." },
  { zh: "巫蠱事連歲不決，武帝疾，來往長楊、五柞宮，望氣者言長安獄中有天子氣，於是武帝遣使者分條中都官，詔獄繫者，無輕重，一切皆殺之。", literal: "The witchcraft affair went unresolved for successive years; Emperor Wu was ill, coming and going between Changyang and Wuzuo palaces; qi-readers said there was Son-of-Heaven qi in Chang'an's prisons; thereupon Emperor Wu sent envoys to itemize separately the capital officials—those held in edict prisons, without regard to severity, all were to be killed.", idiomatic: "The witchcraft affair went unresolved for successive years; Emperor Wu was ill, coming and going between Changyang and Wuzuo palaces; qi-readers said there was Son-of-Heaven qi in Chang'an's prisons; thereupon Emperor Wu sent envoys to itemize separately the capital officials—those held in edict prisons, without regard to severity, all were to be killed." },
  { zh: "內謁者令郭穰夜到郡邸獄，吉閉門拒使者不納，曰：「皇曾孫在。", literal: "Inner Usher-in-Chief Guo Rang came by night to the commandery hostel prison; Ji shut the gate, refused the envoy, and would not admit him, saying: \"The imperial great-grandson is here.", idiomatic: "Inner Usher-in-Chief Guo Rang came by night to the commandery hostel prison; Ji shut the gate, refused the envoy, and would not admit him, saying, \"The imperial great-grandson is here." },
  { zh: "他人無辜死者猶不可，況親曾孫乎！", literal: "Others who died innocent still could not be allowed—how much more a close great-grandson!", idiomatic: "Others who died innocent still could not be allowed—how much more a close great-grandson!" },
  { zh: "」相守至天明，不得入。", literal: "\" They held each other off until dawn; he could not enter.", idiomatic: "\" They held each other off until dawn; he could not enter." },
  { zh: "穰還，以聞，因劾奏吉。", literal: "Rang returned and reported it, and thereby impeached and memorialized Ji.", idiomatic: "Rang returned and reported it, and thereby impeached and memorialized Ji." },
  { zh: "武帝亦寤，曰：「天使之也。", literal: "Emperor Wu also awoke and said: \"Heaven sent him.", idiomatic: "Emperor Wu also awoke and said, \"Heaven sent him." },
  { zh: "」因赦天下。", literal: "\" Thereupon he amnestied all under Heaven.", idiomatic: "\" Thereupon he amnestied all under Heaven." },
  { zh: "郡邸獄繫者，獨賴吉得生。", literal: "Of those held in the commandery hostel prison, they alone relied on Ji to live.", idiomatic: "Of those held in the commandery hostel prison, they alone relied on Ji to live." },
  { zh: "既而吉謂守丞誰如：「皇孫不當在官。", literal: "Afterward Ji told the prison warden Shei Ru: \"The imperial grandson ought not to be in an office.", idiomatic: "Afterward Ji told the prison warden Shei Ru, \"The imperial grandson ought not to be in an office." },
  { zh: "」使誰如移書京兆尹，遣與胡組俱送；", literal: "\" He had Shei Ru send a letter to the Governor of Jingzhao to dispatch him together with Huzu;", idiomatic: "\" He had Shei Ru send a letter to the Governor of Jingzhao to dispatch him together with Huzu;" },
  { zh: "京兆尹不受，復還。", literal: "the Governor of Jingzhao would not receive him, and he returned.", idiomatic: "the Governor of Jingzhao would not receive him, and he returned." },
  { zh: "及組日滿當去，皇孫思慕，吉以私錢雇組令留，與郭徵卿並養，養月，乃遣組去。", literal: "When Huzu's term was full and she was to leave, the imperial grandson yearned for her; Ji with private money hired Huzu to stay; together with Guo Zhengqing they jointly nursed him; after a month of nursing he sent Huzu away.", idiomatic: "When Huzu's term was full and she was to leave, the imperial grandson yearned for her; Ji with private money hired Huzu to stay; together with Guo Zhengqing they jointly nursed him; after a month of nursing he sent Huzu away." },
  { zh: "後少內嗇夫白吉曰：「食皇孫無詔令。", literal: "Later the junior palace provisioner reported to Ji: \"Feeding the imperial grandson has no edict.", idiomatic: "Later the junior palace provisioner reported to Ji, \"Feeding the imperial grandson has no edict." },
  { zh: "」時吉得食米、肉，月月以給皇曾孫。", literal: "\" At that time Ji obtained food, rice, and meat and month by month supplied the imperial great-grandson.", idiomatic: "\" At that time Ji obtained food, rice, and meat and month by month supplied the imperial great-grandson." },
  { zh: "曾孫病，幾不全者數焉，吉數敕保養乳母加致醫藥，視遇甚有恩惠。", literal: "The great-grandson fell ill and several times nearly did not survive; Ji repeatedly ordered the protectors and wet-nurses to add medicine, and his regard and treatment were very full of kindness.", idiomatic: "The great-grandson fell ill and several times nearly did not survive; Ji repeatedly ordered the protectors and wet-nurses to add medicine, and his regard and treatment were very full of kindness." },
  { zh: "吉聞史良娣有母貞君及兄恭，乃載皇曾孫以付之。", literal: "Ji heard Lady Shi's worthy mother had the Chaste Lady and an elder brother Gong; he thereupon carried the imperial great-grandson and handed him over to them.", idiomatic: "Ji heard Lady Shi's worthy mother had the Chaste Lady and an elder brother Gong; he thereupon carried the imperial great-grandson and handed him over to them." },
  { zh: "貞君年老，見孫孤，甚哀之，自養視焉。", literal: "The Chaste Lady was old; seeing the grandson orphaned, she deeply pitied him and herself nursed and watched over him.", idiomatic: "The Chaste Lady was old; seeing the grandson orphaned, she deeply pitied him and herself nursed and watched over him." },
  { zh: "後有詔掖庭養視，上屬籍宗正。", literal: "Later there was an edict that the Palace Rear Garden should nurse and watch him; the emperor entrusted his registration to the Director of the Imperial Clan.", idiomatic: "Later there was an edict that the Palace Rear Garden should nurse and watch him; the emperor entrusted his registration to the Director of the Imperial Clan." },
  { zh: "時掖庭令張賀，嘗事戾太子，思顧舊恩，哀曾孫，奉養甚謹，以私錢供給，教書。", literal: "At that time Palace Rear Garden Director Zhang He had once served Prince Li; thinking back on old grace, he pitied the great-grandson, supported and nursed him very carefully, supplied him with private money, and taught him books.", idiomatic: "At that time Palace Rear Garden Director Zhang He had once served Prince Li; thinking back on old grace, he pitied the great-grandson, supported and nursed him very carefully, supplied him with private money, and taught him books." },
  { zh: "既壯，賀欲以女孫妻之。", literal: "When he was grown, He wished to give his granddaughter in marriage to him.", idiomatic: "When he was grown, He wished to give his granddaughter in marriage to him." },
  { zh: "是時昭帝始冠，長八尺二寸。", literal: "At this time Emperor Zhao had just capped his years and was eight feet two inches tall.", idiomatic: "At this time Emperor Zhao had just capped his years and was eight feet two inches tall." },
  { zh: "賀弟安世為右將軍，輔政，聞賀稱譽皇曾孫，欲妻以女，怒曰：「曾孫乃衛太子後也，幸得以庶人衣食縣官足矣，勿復言予女事！", literal: "He's younger brother Anshi was Right General assisting government; hearing He praise the imperial great-grandson, he wished to give his daughter in marriage to him and angrily said: \"The great-grandson is the heir of the Wei crown prince; it is luck enough that as a commoner he eats and is clothed by the district officials—do not again speak of giving a daughter!", idiomatic: "He's younger brother Anshi was Right General assisting government; hearing He praise the imperial great-grandson, he wished to give his daughter in marriage to him and angrily said, \"The great-grandson is the heir of the Wei crown prince; it is luck enough that as a commoner he eats and is clothed by the district officials—do not again speak of giving a daughter!" },
  { zh: "」於是賀止。", literal: "\" Thereupon He stopped.", idiomatic: "\" Thereupon He stopped." },
  { zh: "時暴室嗇夫許廣漢有女，賀乃置酒請廣漢，酒酣，為言：「曾孫體近，下乃關內侯，可妻也。", literal: "At that time Wardrobe Provisioner Xu Guanghan had a daughter; He thereupon set out wine and invited Guanghan; when the wine was deep, he spoke for him: \"The great-grandson's person is close; below he will be Marquis within the Passes—he can be married.", idiomatic: "At that time Wardrobe Provisioner Xu Guanghan had a daughter; He thereupon set out wine and invited Guanghan; when the wine was deep, he spoke for him, \"The great-grandson's person is close; below he will be Marquis within the Passes—he can be married." },
  { zh: "」廣漢許諾。", literal: "\" Guanghan promised.", idiomatic: "\" Guanghan promised." },
  { zh: "明日，嫗聞之，怒。", literal: "The next day the old woman heard it and was angry.", idiomatic: "The next day the old woman heard it and was angry." },
  { zh: "廣漢重令人為介，遂與曾孫。", literal: "Guanghan again had someone act as go-between, and thereupon he was given to the great-grandson.", idiomatic: "Guanghan again had someone act as go-between, and thereupon he was given to the great-grandson." },
  { zh: "賀以家財聘之。", literal: "He used family wealth as betrothal gift.", idiomatic: "He used family wealth as betrothal gift." },
  { zh: "曾孫因依倚廣漢兄弟及祖母家史氏，受《詩》於東海澓中翁，高材好學；", literal: "The great-grandson thereby relied on Guanghan's brothers and his grandmother's Shi clan; he received the Odes from Old Man Fu of the Middle in Donghai—talented and fond of learning;", idiomatic: "The great-grandson thereby relied on Guanghan's brothers and his grandmother's Shi clan; he received the Odes from Old Man Fu of the Middle in Donghai—talented and fond of learning;" },
  { zh: "然亦喜遊俠，鬥雞走狗，以是俱知-{閭里}-奸邪，吏治得失。", literal: "yet he also delighted in roaming knights-errant, cockfighting, and dog-racing—thereby altogether knowing -{閭里}- wickedness and rectitude and officials' governance gains and losses.", idiomatic: "yet he also delighted in roaming knights-errant, cockfighting, and dog-racing—thereby altogether knowing -{閭里}- wickedness and rectitude and officials' governance gains and losses." },
  { zh: "數上下諸陵，周遍三輔，嘗困於蓮勺鹵中，尤樂杜、鄠之間，率常在下杜。", literal: "He repeatedly went up and down the various mausoleums and circled the Three Metropolises; he once was stranded in the Liaoshao salt marshes; he especially delighted in the region between Du and Hu—he mostly was often at Lower Du.", idiomatic: "He repeatedly went up and down the various mausoleums and circled the Three Metropolises; he once was stranded in the Liaoshao salt marshes; he especially delighted in the region between Du and Hu—he mostly was often at Lower Du." },
  { zh: "時會朝請，舍長安尚冠-{里}-。", literal: "When court audiences were held he lodged in Chang'an at Shangguan -{里}-.", idiomatic: "When court audiences were held he lodged in Chang'an at Shangguan -{里}-." },
  { zh: "及昌邑王廢，霍光與張安世諸大臣議所立，未定。", literal: "When the King of Changyi was deposed, Huo Guang with Zhang Anshi and the various great ministers deliberated whom to establish—it was not settled.", idiomatic: "When the King of Changyi was deposed, Huo Guang with Zhang Anshi and the various great ministers deliberated whom to establish—it was not settled." },
  { zh: "丙吉奏記光曰：「將軍事孝武皇帝，受襁褓之屬，任天下之寄。", literal: "Bing Ji submitted a note to Guang, saying: \"The general served Emperor Wu of Filial Piety, received the entrustment in swaddling clothes, and bore the charge of all under Heaven.", idiomatic: "Bing Ji submitted a note to Guang, saying, \"The general served Emperor Wu of Filial Piety, received the entrustment in swaddling clothes, and bore the charge of all under Heaven." },
  { zh: "孝昭皇帝早崩亡嗣，海內憂懼，欲亟聞嗣主。", literal: "Emperor Zhao of Filial Piety early perished without an heir; within the seas there was worry and fear, wishing quickly to hear of a successor lord.", idiomatic: "Emperor Zhao of Filial Piety early perished without an heir; within the seas there was worry and fear, wishing quickly to hear of a successor lord." },
  { zh: "發喪之日，以大誼立後，所立非其人，復以大誼廢之；", literal: "On the day mourning was raised, by great principle he established a successor; the one established was not the right person, and again by great principle he deposed him;", idiomatic: "On the day mourning was raised, by great principle he established a successor; the one established was not the right person, and again by great principle he deposed him;" },
  { zh: "天下莫不服焉。", literal: "all under Heaven none failed to submit to it.", idiomatic: "all under Heaven none failed to submit to it." },
  { zh: "方今社稷、宗廟、群生之命在將軍之壹舉，竊伏聽於眾庶，察其所言諸侯、宗室在列位者，未有所聞於民間也。", literal: "Now the altars of soil and grain, the ancestral temples, and the lives of the masses rest on the general's one act; your subject privately bows and listens to the multitude—examining what they say, of the feudal lords and imperial clansmen in ranked positions, nothing has been heard from among the people.", idiomatic: "Now the altars of soil and grain, the ancestral temples, and the lives of the masses rest on the general's one act; your subject privately bows and listens to the multitude—examining what they say, of the feudal lords and imperial clansmen in ranked positions, nothing has been heard from among the people." },
  { zh: "而遺詔所養武帝曾孫名病已在掖庭、外家者，吉前使居郡邸時，見其幼少；", literal: "Yet the late emperor's edict–nurtured imperial great-grandson of Emperor Wu named Bingyi, who is in the Palace Rear Garden and at his maternal kin's—when Ji formerly had him dwell at the commandery hostel, he saw him young;", idiomatic: "Yet the late emperor's edict–nurtured imperial great-grandson of Emperor Wu named Bingyi, who is in the Palace Rear Garden and at his maternal kin's—when Ji formerly had him dwell at the commandery hostel, he saw him young;" },
  { zh: "至今十八九矣，通經術，有美材，行安而節和。", literal: "until now he is eighteen or nineteen; he has mastered the classics, has fine talent, and his conduct is steady and his temperance harmonious.", idiomatic: "until now he is eighteen or nineteen; he has mastered the classics, has fine talent, and his conduct is steady and his temperance harmonious." },
  { zh: "願將軍詳大義，參以蓍龜豈宜，褒顯先使入侍，令天下昭然知之，然後決定大策，天下幸甚！", literal: "Your subject wishes the general to examine great principle, consult tortoise and milfoil on what is fitting, honor and display him first and have him enter attendance, let all under Heaven clearly know it, and then decide the great policy—all under Heaven would be greatly fortunate!", idiomatic: "Your subject wishes the general to examine great principle, consult tortoise and milfoil on what is fitting, honor and display him first and have him enter attendance, let all under Heaven clearly know it, and then decide the great policy—all under Heaven would be greatly fortunate!" },
  { zh: "」杜延年亦知曾孫德美，勸光、安世立焉。", literal: "\" Du Yanian also knew the great-grandson's virtue and beauty and urged Guang and Anshi to establish him.", idiomatic: "\" Du Yanian also knew the great-grandson's virtue and beauty and urged Guang and Anshi to establish him." },
  { zh: "秋，七月，光坐庭中，會丞相以下議定所立，遂復與丞相敞等上奏曰：「孝武皇帝曾孫病已，年十八，師受《詩》、《論語》、《孝經》，躬行節儉，慈仁愛人，可以嗣孝昭皇帝後，奉承祖宗廟，子萬姓。", literal: "In autumn, the seventh month, Guang sat in the courtyard and convened the chancellor and below to settle whom to establish; he thereupon again with Chancellor Chang and others submitted a memorial, saying: \"Emperor Wu of Filial Piety's imperial great-grandson Bingyi, age eighteen, has been instructed in the Odes, Analects, and Classic of Filial Piety, personally practices frugality, is kindly and humane, and can succeed after Emperor Zhao of Filial Piety, receive and uphold the ancestral temples, and be lord to the myriad people.", idiomatic: "In autumn, the seventh month, Guang sat in the courtyard and convened the chancellor and below to settle whom to establish; he thereupon again with Chancellor Chang and others submitted a memorial, saying, \"Emperor Wu of Filial Piety's imperial great-grandson Bingyi, age eighteen, has been instructed in the Odes, Analects, and Classic of Filial Piety, personally practices frugality, is kindly and humane, and can succeed after Emperor Zhao of Filial Piety, receive and uphold the ancestral temples, and be lord to the myriad people." },
  { zh: "臣昧死以聞！", literal: "Your subjects risk death to report!", idiomatic: "Your subjects risk death to report!" },
  { zh: "」皇太后詔曰：「可。", literal: "\" The empress dowager edicted: \"Approved.", idiomatic: "\" The empress dowager edicted, \"Approved." },
  { zh: "」光遣宗正德至曾孫家尚冠-{里}-，洗沐，賜御衣；", literal: "\" Guang sent Director of the Imperial Clan De to the great-grandson's home at Shangguan -{里}- to bathe and wash him and bestow imperial robes;", idiomatic: "\" Guang sent Director of the Imperial Clan De to the great-grandson's home at Shangguan -{里}- to bathe and wash him and bestow imperial robes;" },
  { zh: "太僕以軨獵車迎曾孫，就齋宗正府。", literal: "the Grand Coachman with a light hunting carriage welcomed the great-grandson, and he fasted at the Director of the Imperial Clan's office.", idiomatic: "the Grand Coachman with a light hunting carriage welcomed the great-grandson, and he fasted at the Director of the Imperial Clan's office." },
  { zh: "庚申，入未央宮，見皇太后，封為陽武侯。", literal: "On gengshen he entered Weiyang Palace, saw the empress dowager, and was enfeoffed as Marquis of Yangwu.", idiomatic: "On gengshen he entered Weiyang Palace, saw the empress dowager, and was enfeoffed as Marquis of Yangwu." },
  { zh: "已而群臣奏上璽綬，即皇帝位，謁高廟；", literal: "Shortly after, the ministers memorialized and presented the seal and ribbon; he took the imperial throne and visited the High Ancestral Temple;", idiomatic: "Shortly after, the ministers memorialized and presented the seal and ribbon; he took the imperial throne and visited the High Ancestral Temple;" },
  { zh: "尊皇太后為太皇太后。", literal: "he honored the empress dowager as Grand Empress Dowager.", idiomatic: "he honored the empress dowager as Grand Empress Dowager." },
  { zh: "侍御史嚴延年劾奏「大將軍光擅廢立主，無人臣禮，不道。", literal: "Attendant Censor Yan Yannian impeached and memorialized: \"Grand General Guang on his own authority deposed and established the lord, lacked minister's rites, and was without the Way.", idiomatic: "Attendant Censor Yan Yannian impeached and memorialized, \"Grand General Guang on his own authority deposed and established the lord, lacked minister's rites, and was without the Way." },
  { zh: "」奏雖寢，然朝廷肅然敬憚之。", literal: "\" The memorial though was shelved, yet the court was solemn and in reverent awe of him.", idiomatic: "\" The memorial though was shelved, yet the court was solemn and in reverent awe of him." },
  { zh: "----6八月，己巳，安平敬侯楊敞薨。", literal: "----6 In the eighth month, on jisi, Yang Chang, Marquis Jing of Anping, died.", idiomatic: "----6 In the eighth month, on jisi, Yang Chang, Marquis Jing of Anping, died." },
  { zh: "----7九月，大赦天下。", literal: "----7 In the ninth month, amnesty for all under Heaven.", idiomatic: "----7 In the ninth month, there was an amnesty for all under Heaven." },
  { zh: "----8戊寅，蔡義為丞相。", literal: "----8 On wuyin, Cai Yi was made chancellor.", idiomatic: "----8 On wuyin, Cai Yi was appointed chancellor." },
  { zh: "----9初，許廣漢女適皇曾孫，一歲，生子奭。", literal: "----9 At the beginning, Xu Guanghan's daughter was married to the imperial great-grandson; at one year she bore a son Shi.", idiomatic: "----9 At the beginning, Xu Guanghan's daughter was married to the imperial great-grandson; at one year she bore a son Shi." },
  { zh: "數月，曾孫立為帝，許氏為倢伃。", literal: "Several months later the great-grandson was established as emperor; the Xu clan became Lady of Handsome Fairness.", idiomatic: "Several months later the great-grandson was established as emperor; the Xu clan became Lady of Handsome Fairness." },
  { zh: "是時霍將軍有小女與皇太后親，公卿議更立皇后，皆心擬霍將軍女，亦未有言。", literal: "At this time General Huo had a young daughter kin to the empress dowager; the dukes and ministers deliberated on changing and establishing an empress—all inwardly had in mind General Huo's daughter, yet none spoke.", idiomatic: "At this time General Huo had a young daughter kin to the empress dowager; the dukes and ministers deliberated on changing and establishing an empress—all inwardly had in mind General Huo's daughter, yet none spoke." },
  { zh: "上乃詔求微時故劍。", literal: "The emperor thereupon edicted to seek the old sword from his humble days.", idiomatic: "The emperor thereupon edicted to seek the old sword from his humble days." },
  { zh: "大臣知指，白立許倢伃為皇后。", literal: "The great ministers knew his intent and reported to establish Lady Xu of Handsome Fairness as empress.", idiomatic: "The great ministers knew his intent and reported to establish Lady Xu of Handsome Fairness as empress." },
  { zh: "十一月，壬子，立皇后許氏。", literal: "In the eleventh month, on renzi, Empress Xu was established.", idiomatic: "In the eleventh month, on renzi, Empress Xu was established." },
  { zh: "霍光以-{后}-父廣漢刑人，不宜君國；", literal: "Huo Guang, because the -{后}-'s father Guanghan was a punished man, thought him unsuitable to lord the state;", idiomatic: "Huo Guang, because the -{后}-'s father Guanghan was a punished man, thought him unsuitable to lord the state;" },
  { zh: "歲餘，乃封為昌成君。", literal: "after more than a year he was enfeoffed as Lord of Changcheng.", idiomatic: "after more than a year he was enfeoffed as Lord of Changcheng." },
  { zh: "----10太皇太后歸長樂宮。", literal: "----10 The Grand Empress Dowager returned to Changle Palace.", idiomatic: "----10 The Grand Empress Dowager returned to Changle Palace." },
  { zh: "長樂宮初置屯衛。", literal: "Changle Palace for the first time established garrison guards.", idiomatic: "Changle Palace for the first time established garrison guards." },
  { zh: "1春，詔有司論定策安宗廟功。", literal: "1 In spring, an edict ordered the officials to discuss and fix merit for the policy of securing the ancestral temples.", idiomatic: "1 In spring, an edict ordered the officials to discuss and fix merit for the policy of securing the ancestral temples." },
  { zh: "大將軍光益封萬七千戶，與故所食凡二萬戶。", literal: "Grand General Guang was additionally enfeoffed with seventeen thousand households; together with what he formerly ate, in all twenty thousand households.", idiomatic: "Grand General Guang was additionally enfeoffed with seventeen thousand households; together with what he formerly ate, in all twenty thousand households." },
  { zh: "車騎將軍富平侯安世以下益封者十人，封侯者五人，賜爵關內侯者八人。", literal: "Commandant of Cavalry and Chariots Anshi, Marquis of Fuping, and below—ten persons were additionally enfeoffed; five were enfeoffed as marquises; eight were granted the title Marquis within the Passes.", idiomatic: "Commandant of Cavalry and Chariots Anshi, Marquis of Fuping, and below—ten persons were additionally enfeoffed; five were enfeoffed as marquises; eight were granted the title Marquis within the Passes." },
  { zh: "----2大將軍光稽首歸政，上謙讓不受；", literal: "----2 Grand General Guang bowed his head and returned government; the emperor modestly declined and would not receive it;", idiomatic: "----2 Grand General Guang bowed his head and returned government; the emperor modestly declined and would not receive it;" },
  { zh: "諸事皆先關白光，然後奏御。", literal: "all affairs were first brought to Guang's attention, and then memorialized to the throne.", idiomatic: "all affairs were first brought to Guang's attention, and then memorialized to the throne." },
  { zh: "自昭帝時，光子禹及兄孫雲皆為中郎將，雲弟山奉車都尉、侍中、領胡、越兵，光兩女婿為東、西宮衛尉，昆弟、諸婿、外孫皆奉朝請，為諸曹、大夫、騎都尉、給事中，黨親連體，根據於朝廷。", literal: "From Emperor Zhao's time, Guang's son Yu and elder brother's grandson Yun were both Commanders of the Palace Guard; Yun's younger brother Shan was Commandant of the Imperial Carriages, Palace Attendant, and led Hu and Yue troops; Guang's two sons-in-law were Eastern and Western Palace Commandants of the Guard; brothers, sons-in-law, and maternal grandsons all attended court audiences as guests, serving as various bureau heads, grandees, Commandants of Cavalry, and Palace Attendants—faction and kin linked as one body, rooted in the court.", idiomatic: "From Emperor Zhao's time, Guang's son Yu and elder brother's grandson Yun were both Commanders of the Palace Guard; Yun's younger brother Shan was Commandant of the Imperial Carriages, Palace Attendant, and led Hu and Yue troops; Guang's two sons-in-law were Eastern and Western Palace Commandants of the Guard; brothers, sons-in-law, and maternal grandsons all attended court audiences as guests, serving as various bureau heads, grandees, Commandants of Cavalry, and Palace Attendants—faction and kin linked as one body, rooted in the court." },
  { zh: "及昌邑王廢，光權益重，每朝見，上虛己斂容，禮下之已甚。", literal: "When the King of Changyi was deposed, Guang's power grew ever heavier; at each court audience the emperor emptied himself and composed his countenance, honoring and lowering himself to him already to excess.", idiomatic: "When the King of Changyi was deposed, Guang's power grew ever heavier; at each court audience the emperor emptied himself and composed his countenance, honoring and lowering himself to him already to excess." },
  { zh: "----3夏，四月，庚午，地震。", literal: "----3 In summer, the fourth month, on gengwu, there was an earthquake.", idiomatic: "----3 In summer, the fourth month, on gengwu, there was an earthquake." },
  { zh: "----4五月，鳳皇集膠東、千乘。", literal: "----4 In the fifth month, phoenixes gathered at Jiaodong and Qiancheng.", idiomatic: "----4 In the fifth month, phoenixes gathered at Jiaodong and Qiancheng." },
  { zh: "赦天下，勿收田租賦。", literal: "Amnesty for all under Heaven; do not collect field rent and tax.", idiomatic: "There was an amnesty for all under Heaven; field rent and tax were not collected." },
  { zh: "----5六月，詔曰：「故皇太子在湖，未有號謚，歲時祠；", literal: "----5 In the sixth month, an edict said: \"The former crown prince is at Hu and has no posthumous title or seasonal sacrifices;", idiomatic: "----5 In the sixth month, an edict said, \"The former crown prince is at Hu and has no posthumous title or seasonal sacrifices;" },
  { zh: "其議謚，置園邑。", literal: "discuss his posthumous title and establish a park estate.", idiomatic: "discuss his posthumous title and establish a park estate." },
  { zh: "」有司奏請：「禮，為人後者，為之子也；", literal: "\" The officials memorialized and requested: \"By ritual, one who becomes another's successor is as his son;", idiomatic: "\" The officials memorialized and requested, \"By ritual, one who becomes another's successor is as his son;" },
  { zh: "故降其父母，不得祭，尊祖之義也。", literal: "therefore one lowers his parents and may not sacrifice to them—the meaning of honoring ancestors.", idiomatic: "therefore one lowers his parents and may not sacrifice to them—the meaning of honoring ancestors." },
  { zh: "陛下為孝昭帝後，承祖宗之祀，愚以為親謚宜曰悼，母曰-{悼后}-；", literal: "Your Majesty succeeds after Emperor Zhao of Filial Piety and receives the ancestral sacrifices; your subjects think the parent's posthumous title should be called Mournful, the mother called -{悼后}-;", idiomatic: "Your Majesty succeeds after Emperor Zhao of Filial Piety and receives the ancestral sacrifices; your subjects think the parent's posthumous title should be called Mournful, the mother called -{悼后}-;" },
  { zh: "故皇太子謚曰戾，史良娣曰戾夫人。", literal: "the former crown prince's posthumous title is called Harsh, Lady Shi the worthy is called Lady Harsh.", idiomatic: "the former crown prince's posthumous title is called Harsh, Lady Shi the worthy is called Lady Harsh." },
  { zh: "」皆改葬焉。", literal: "\" All were reburied.", idiomatic: "\" All were reburied." },
  { zh: "----6秋，七月，詔立燕剌王太子建為廣陽王；", literal: "----6 In autumn, the seventh month, an edict established the King of Yan's spur-king crown prince Jian as King of Guangyang;", idiomatic: "----6 In autumn, the seventh month, an edict established the King of Yan's spur-king crown prince Jian as King of Guangyang;" },
  { zh: "立廣陵王胥少子弘為高密王。", literal: "it established the King of Guangling Xu's youngest son Hong as King of Gaomi.", idiomatic: "it established the King of Guangling Xu's youngest son Hong as King of Gaomi." },
  { zh: "----7初，上官桀與霍光爭權，光既誅桀，遂遵武帝法度，以刑罰痛繩群下，由是俗吏皆尚嚴酷以為能；", literal: "----7 At the beginning, Shangguan Jie contended for power with Huo Guang; after Guang had executed Jie, he thereupon followed Emperor Wu's standards, using punishments to tightly bind the masses below—thereby vulgar officials all prized severity and cruelty as ability;", idiomatic: "----7 At the beginning, Shangguan Jie contended for power with Huo Guang; after Guang had executed Jie, he thereupon followed Emperor Wu's standards, using punishments to tightly bind the masses below—thereby vulgar officials all prized severity and cruelty as ability;" },
  { zh: "而河南太守丞淮陽黃霸獨用寬和為名。", literal: "yet Assistant Governor Huang Ba of Huaiyang in Henan alone used leniency and harmony as his reputation.", idiomatic: "yet Assistant Governor Huang Ba of Huaiyang in Henan alone used leniency and harmony as his reputation." },
  { zh: "上在民間時，知百姓苦吏急也，聞霸持法平，乃召以為廷尉正；", literal: "When the emperor was among the people he knew the common people suffered from officials' harshness; hearing Ba held the law evenly, he thereupon summoned him and made him Corrector of the Commandant of Justice;", idiomatic: "When the emperor was among the people he knew the common people suffered from officials' harshness; hearing Ba held the law evenly, he thereupon summoned him and made him Corrector of the Commandant of Justice;" },
  { zh: "數決疑獄，庭中稱平。", literal: "he repeatedly decided doubtful cases, and within the court they called him even.", idiomatic: "he repeatedly decided doubtful cases, and within the court they called him even." },
  { zh: "1春，大司農田延年有罪自殺。", literal: "1 In spring, Grand Minister of Agriculture Tian Yannian, guilty of a crime, killed himself.", idiomatic: "1 In spring, Grand Minister of Agriculture Tian Yannian, guilty of a crime, killed himself." },
  { zh: "昭帝之喪，大司農僦民車，延年詐增僦直，盜取錢三千萬，為怨家所告。", literal: "At Emperor Zhao's mourning, the Grand Minister of Agriculture hired the people's carts; Yannian falsely increased the hire price and stole thirty million cash; he was reported by an enemy family.", idiomatic: "At Emperor Zhao's mourning, the Grand Minister of Agriculture hired the people's carts; Yannian falsely increased the hire price and stole thirty million cash; he was reported by an enemy family." },
  { zh: "霍將軍召問延年，欲為道地。", literal: "The Grand General summoned and questioned Yannian, wishing to show him a way out.", idiomatic: "Grand General Huo summoned and questioned Yannian, wishing to find him grounds for leniency." },
  { zh: "延年抵曰：「無有是事！", literal: "Yannian resisted and said: \"There is no such thing!", idiomatic: "Yannian pushed back and said, \"There is no such thing!" },
  { zh: "」光曰：「即無事，當窮竟！", literal: "\" Guang said: \"Even if there is nothing, it must be thoroughly investigated!", idiomatic: "\" Guang said, \"Even if there is nothing to it, it must be investigated to the end!" },
  { zh: "」御史大夫田廣明謂太僕杜延年曰：「《春秋》之義，以功覆過。", literal: "\" The Censor-in-Chief Tian Guangming said to Grand Master of Husbandry Du Yannian: \"The meaning of the Spring and Autumn Annals is that merit covers offense.", idiomatic: "\" Censor-in-Chief Tian Guangming said to Grand Master of Husbandry Du Yannian, \"The Spring and Autumn principle is that merit may cover offense." },
  { zh: "當廢昌邑王時，非田子賓之言，大事不成。", literal: "When deposing the King of Changyi, without Tian Zibin's words the great affair would not have succeeded.", idiomatic: "When deposing the King of Changyi, without Tian Zibin's counsel the great affair would not have succeeded." },
  { zh: "今縣官出三千萬自乞之，何哉？", literal: "Now the official treasury puts out thirty million to beg for himself—what is this?", idiomatic: "Now the government is putting out thirty million to plead on his behalf—what is this?" },
  { zh: "願以愚言白大將軍。", literal: "I wish to present my foolish words to inform the Grand General.", idiomatic: "I wish to present my humble counsel to the Grand General." },
  { zh: "」延年言之大將軍，大將軍曰：「誠然，實勇士也！", literal: "\" Yannian reported it to the Grand General; the Grand General said: \"It is truly so—he is indeed a brave warrior!", idiomatic: "\" Yannian reported this to the Grand General, who said, \"It is true—he is indeed a brave warrior!" },
  { zh: "當發大議時，震動朝廷，」光因舉手自撫心曰：「使我至今病悸。", literal: "When the great debate was launched, it shook the court,\" Guang thereupon raised his hand and stroked his heart, saying: \"It makes my heart palpitate with illness even now.", idiomatic: "When that great debate was launched, it shook the court,\" Guang raised his hand to his heart and said, \"It still makes my heart race with fear." },
  { zh: "謝田大夫曉大司農，通往就獄，得公議之。", literal: "Thank Censor Tian; inform the Grand Minister of Agriculture; enable him to proceed to prison and obtain the court's collective deliberation.", idiomatic: "Thank Censor Tian; inform the Grand Minister of Agriculture; let him go to prison and obtain a collective court judgment." },
  { zh: "」田大夫使人語延年。", literal: "\" The Censor sent someone to speak to Yannian.", idiomatic: "\" The Censor sent someone to speak to Yannian." },
  { zh: "延年曰：「幸縣官寬我耳，何面目入牢獄，使眾人指笑我，卒徒唾吾背乎？", literal: "Yannian said: \"Fortunately the official treasury will be lenient with me—what face have I to enter prison, let the multitude point and laugh at me, and convicts and soldiers spit on my back?", idiomatic: "Yannian said, \"Fortunately the government will be lenient with me—what face have I to enter prison, let everyone point and laugh at me, and convicts spit on my back?" },
  { zh: "」即閉閣獨居齋舍，偏袒，持刀東西步。", literal: "\" He immediately shut the door, lived alone in his study quarters, bared one shoulder, and paced east and west with a knife in hand.", idiomatic: "\" He shut his door, lived alone in his study, bared one shoulder, and paced east and west with a knife in hand." },
  { zh: "數日，使者召延年詣廷尉。", literal: "Several days later, an envoy summoned Yannian to the Director of Justice.", idiomatic: "Several days later, an envoy summoned Yannian to the Director of Justice." },
  { zh: "聞鼓聲，自刎死。", literal: "Hearing the drum sound, he cut his own throat and died.", idiomatic: "Hearing the drum, he cut his own throat and died." },
  { zh: "----2夏，五月，詔曰：「孝武皇帝躬仁誼，勵威武，功德茂盛，而廟樂未稱，聯甚悼焉。", literal: "----2 In summer, the fifth month, an edict said: \"Emperor Xiao Wu personally practiced benevolence and righteousness, encouraged martial prowess, and his merit and virtue were luxuriant, yet the temple music does not match him—We are deeply grieved.", idiomatic: "----2 In summer, the fifth month, an edict said, \"Emperor Xiao Wu personally practiced benevolence and righteousness, encouraged martial prowess, and his merit and virtue were abundant, yet his temple music is unworthy—We are deeply grieved." },
  { zh: "其與列侯、二千石、博士議。", literal: "Let him deliberate with the ranked marquises, the two-thousand-bushel officials, and the erudites.", idiomatic: "Let him deliberate with the marquises, two-thousand-bushel officials, and erudites." },
  { zh: "」於是群臣大議庭中，皆曰：「宜如詔書。", literal: "\" Thereupon the ministers greatly debated in the court, all saying: \"It should be as the edict states.", idiomatic: "\" Thereupon the ministers debated at length in court, all saying, \"It should be as the edict states." },
  { zh: "」長信少府夏侯勝獨曰：「武帝雖有攘四夷、廣土境之功，然多殺士眾，竭民財力，奢泰無度，天下虛耗，百姓流離，物故者半，蝗蟲大起，赤地數千里，或人民相食，畜積至今未復；", literal: "\" Director of Changxin Household Xiahou Sheng alone said: \"Although Emperor Wu had the achievement of driving off the four barbarians and expanding the territory, yet he killed many soldiers and masses, exhausted the people's wealth and strength, was extravagant beyond measure—the realm was drained empty, the people were displaced, half died, locusts arose greatly, thousands of li of bare red earth, sometimes people ate one another, and stores have not recovered to this day;", idiomatic: "\" Director of Changxin Household Xiahou Sheng alone said, \"Although Emperor Wu had the achievement of driving off the four barbarians and expanding the borders, he killed many soldiers and civilians, exhausted the people's wealth, was extravagant beyond measure—the realm was drained, the people displaced, half perished, locusts swarmed, thousands of li lay bare, people sometimes ate one another, and stores have not recovered to this day;" },
  { zh: "無德澤於民，不宜為立廟樂。", literal: "he had no benevolent favor toward the people and is not fit to have temple music established.", idiomatic: "he bestowed no benevolent favor on the people and is not fit to have temple music established." },
  { zh: "」公卿共難勝曰：「此詔書也。", literal: "\" The high ministers together challenged Sheng, saying: \"This is an imperial edict.", idiomatic: "\" The high ministers together challenged Sheng, saying, \"This is an imperial edict." },
  { zh: "」勝曰：「詔書不可用也。", literal: "\" Sheng said: \"The edict cannot be used.", idiomatic: "\" Sheng said, \"The edict cannot be followed." },
  { zh: "人臣之誼，宜直言正論，非苟阿意順指。", literal: "The duty of a minister is to speak straight and argue correctly—not to fawn to please and follow the finger.", idiomatic: "A minister's duty is to speak frankly and argue rightly—not to fawn and follow every whim." },
  { zh: "議已出口，雖死不悔！", literal: "The discussion has already left my mouth—even if I die I will not regret it!", idiomatic: "What I have said is already spoken—even if I die I will not regret it!" },
  { zh: "」於是丞相、御史劾奏勝非議詔書，毀先帝，不道；", literal: "\" Thereupon the Chancellor and Censor impeached Sheng for criticizing the edict, slandering the former emperor, and impiety;", idiomatic: "\" Thereupon the chancellor and censor impeached Sheng for criticizing the edict, slandering the former emperor, and impiety;" },
  { zh: "及丞相長史黃霸阿縱勝，不舉劾；", literal: "and the Chancellor's Chief Clerk Huang Ba indulged and indulged Sheng, failing to impeach;", idiomatic: "and the chancellor's chief clerk Huang Ba indulged Sheng and failed to impeach him;" },
  { zh: "俱下獄。", literal: "both were sent to prison.", idiomatic: "both were imprisoned." },
  { zh: "有司遂請尊孝武帝廟為世宗廟，奏《盛德》、《文始五行》之舞。", literal: "The responsible offices thereupon requested to honor Emperor Xiao Wu's temple as the Shizong Temple and perform the dances \"Abundant Virtue\" and \"Wen Shi Five Elements.\"", idiomatic: "The responsible offices requested honoring Emperor Xiao Wu's temple as the Shizong Temple and performing the dances \"Abundant Virtue\" and \"Wen Shi Five Elements.\"" },
  { zh: "武帝巡狩所幸郡國皆立廟，如高祖、太宗焉。", literal: "In every commandery and state where Emperor Wu toured and favored, temples were established, as with Gaozu and Taizong.", idiomatic: "In every commandery and state Emperor Wu had favored on his tours, temples were established, as with Gaozu and Taizong." },
  { zh: "夏侯勝、黃霸既久繫，霸欲從勝受《尚書》，勝辭以罪死。", literal: "Xiahou Sheng and Huang Ba, having long been imprisoned, Ba wished to receive the Documents from Sheng; Sheng declined on the grounds that he would die for his offense.", idiomatic: "Xiahou Sheng and Huang Ba, long imprisoned, wished to study the Documents with Sheng; Sheng declined, saying he would die for his offense." },
  { zh: "霸曰：「朝聞道，夕死可矣。", literal: "Ba said: \"If one hears the Way in the morning, one may die in the evening.", idiomatic: "Ba said, \"If one hears the Way in the morning, one may die in the evening." },
  { zh: "」勝賢其言，遂授之。", literal: "\" Sheng esteemed his words and thereupon taught him.", idiomatic: "\" Sheng admired his words and thereupon taught him." },
  { zh: "繫再更冬，講論不怠。", literal: "Imprisoned through two more winters, they lectured and discussed without slackening.", idiomatic: "Imprisoned through two more winters, they lectured without slackening." },
  { zh: "----3初，烏孫公主死，漢復以楚王戊之孫解憂為公主，妻岑娶。", literal: "----3 Initially the Wusun princess died; Han again made Jieyou, granddaughter of King Wu of Chu, princess and married her to Cenju.", idiomatic: "----3 Initially the Wusun princess died; Han again made Jieyou, granddaughter of King Wu of Chu, a princess and married her to Cenju." },
  { zh: "岑娶胡婦子泥靡尚小，岑娶且死，以國與季父大祿子翁歸靡，曰：「泥靡大，以國歸之。", literal: "Cenju's son by a Hu woman, Nimi, was still young; as Cenju was about to die, he gave the state to his younger father's son, the Grand Captain's son Wengguimi, saying: \"When Nimi is grown, return the state to him.", idiomatic: "Cenju's son by a Hu woman, Nimi, was still young; as Cenju was dying, he gave the state to his uncle's son Wengguimi, saying, \"When Nimi is grown, return the state to him." },
  { zh: "」翁歸靡既立，號肥王，復尚楚主，生三男、兩女。", literal: "\" Wengguimi, once installed, was titled the Fat King; he again married the Chu princess and begot three sons and two daughters.", idiomatic: "\" Once installed, Wengguimi was titled the Fat King; he again married the Chu princess and had three sons and two daughters." },
  { zh: "長男曰元貴靡，次曰萬年，次曰大樂。", literal: "The eldest son was called Yuanguimi, the second Wannian, the third Dale.", idiomatic: "The eldest son was Yuanguimi, the second Wannian, the third Dale." },
  { zh: "昭帝時，公主上書言：「匈奴與車師共侵烏孫，唯天子幸救之。", literal: "In Emperor Zhao's time the princess memorialized, saying: \"The Xiongnu and Cheshi together invade Wusun—only the Son of Heaven may deign to save us.", idiomatic: "In Emperor Zhao's time the princess memorialized, \"The Xiongnu and Cheshi together invade Wusun—only the Son of Heaven can save us." },
  { zh: "」漢養士馬，議擊匈奴。", literal: "\" Han raised soldiers and horses and debated attacking the Xiongnu.", idiomatic: "\" Han raised troops and horses and debated attacking the Xiongnu." },
  { zh: "會昭帝崩，上遣光祿大夫常惠使烏孫。", literal: "It happened Emperor Zhao died; the emperor dispatched Palace Counselor Chang Hui as envoy to Wusun.", idiomatic: "Emperor Zhao died; the emperor dispatched Palace Counselor Chang Hui as envoy to Wusun." },
  { zh: "烏孫公主及昆彌皆遣使上書，言：「匈奴復連發大兵，侵擊烏孫。", literal: "The Wusun princess and the kunmi both sent envoys memorializing, saying: \"The Xiongnu again repeatedly dispatch great armies to invade and strike Wusun.", idiomatic: "The Wusun princess and the kunmi both memorialized, \"The Xiongnu again repeatedly dispatch great armies to invade Wusun." },
  { zh: "使使謂烏孫，『趣持公主來！", literal: "They send envoys telling Wusun, 'Hurry and bring the princess here!", idiomatic: "They send envoys telling Wusun, 'Hurry and bring the princess here!" },
  { zh: "』欲隔絕漢。", literal: "' wishing to cut off Han.", idiomatic: "' intending to sever ties with Han." },
  { zh: "昆彌願發國精兵五萬騎，盡力擊匈奴。", literal: "The kunmi wishes to dispatch the state's elite troops, fifty thousand horsemen, and strike the Xiongnu with full force.", idiomatic: "The kunmi wishes to dispatch fifty thousand elite horsemen and strike the Xiongnu with full force." },
  { zh: "唯天子出兵以救公主、昆彌！", literal: "Only the Son of Heaven must dispatch troops to save the princess and the kunmi!", idiomatic: "Only the Son of Heaven can dispatch troops to save the princess and the kunmi!" },
  { zh: "」先是匈奴數侵漢邊，漢亦欲討之。", literal: "\" Earlier the Xiongnu had repeatedly invaded Han's borders, and Han also wished to chastise them.", idiomatic: "\" Earlier the Xiongnu had repeatedly invaded Han's borders, and Han also wished to chastise them." },
  { zh: "秋，大發兵，遣御史大夫田廣明為祁連將軍，四萬餘騎，出西河；", literal: "In autumn great forces were raised; the Censor-in-Chief Tian Guangming was made General of Qilian, with more than forty thousand horsemen, out from Xihe;", idiomatic: "In autumn great forces were raised; Censor-in-Chief Tian Guangming was made General of Qilian with more than forty thousand horsemen, marching out from Xihe;" },
  { zh: "度遼將軍范明友三萬餘騎，出張掖；", literal: "General Crossing the Liao Fan Mingyou with more than thirty thousand horsemen, out from Zhangye;", idiomatic: "General Crossing the Liao Fan Mingyou with more than thirty thousand horsemen, out from Zhangye;" },
  { zh: "前將軍韓增三萬餘騎，出雲中；", literal: "Forward General Han Zeng with more than thirty thousand horsemen, out from Yunzhong;", idiomatic: "Forward General Han Zeng with more than thirty thousand horsemen, out from Yunzhong;" },
  { zh: "後將軍趙充國為蒲類將軍，三萬餘騎，出酒泉；", literal: "Rear General Zhao Chongguo as General of Pu Lei with more than thirty thousand horsemen, out from Jiuquan;", idiomatic: "Rear General Zhao Chongguo as General of Pu Lei with more than thirty thousand horsemen, out from Jiuquan;" },
  { zh: "雲中太守田順為虎牙將軍，三萬餘騎，出五原；", literal: "Governor of Yunzhong Tian Shun as General of Tiger's Teeth with more than thirty thousand horsemen, out from Wuyuan;", idiomatic: "Governor of Yunzhong Tian Shun as General of Tiger's Teeth with more than thirty thousand horsemen, out from Wuyuan;" },
  { zh: "期以出塞各二千餘里。", literal: "they were scheduled to go beyond the passes each more than two thousand li.", idiomatic: "they were to go beyond the passes each more than two thousand li." },
  { zh: "以常惠為校尉，持節護烏孫兵共擊匈奴。", literal: "Chang Hui was made colonel, bearing credentials to oversee Wusun troops jointly striking the Xiongnu.", idiomatic: "Chang Hui was made colonel, bearing credentials to oversee Wusun troops in a joint attack on the Xiongnu." },
  { zh: "1春，正月，癸亥，恭哀許皇后崩。", literal: "1 In spring, the first month, on guihai, the Respectful and Lamented Empress Xu died.", idiomatic: "1 In spring, the first month, on guihai, the Respectful and Lamented Empress Xu died." },
  { zh: "時霍光夫人顯欲貴其小女成君，道無從。", literal: "At this time Huo Guang's wife Xian wished to exalt her younger daughter Chengjun but found no way.", idiomatic: "At this time Huo Guang's wife Xian wished to exalt her younger daughter Chengjun but found no way to do so." },
  { zh: "會-{許后}-當娠，病，女醫-{淳于衍}-者，霍氏所愛，嘗入宮侍皇后疾。", literal: "It happened -{許后}- was about to give birth and was ill; the woman physician -{淳于衍}-, whom the Huo clan favored, had once entered the palace to attend the empress's illness.", idiomatic: "It happened -{許后}- was about to give birth and was ill; the woman physician -{淳于衍}-, favored by the Huo clan, had once entered the palace to attend the empress's illness." },
  { zh: "衍夫賞為掖庭戶衛，謂衍：「可過辭霍夫人，行為我求安池監。", literal: "Yan's husband Shang was a Household Guard of the Palace Apartments and said to Yan: \"You may go and speak to Lady Huo; on the way seek for me the post of Overseer of Anchi.", idiomatic: "Yan's husband Shang was a Household Guard of the Palace Apartments and told Yan, \"You may visit Lady Huo; on the way ask for me the post of Overseer of Anchi." },
  { zh: "」衍如言報顯，顯因生心，辟左右，謂衍曰：「少夫幸報我以事，我亦欲報少夫，可乎？", literal: "\" Yan reported as told to Xian; Xian thereupon conceived a plan, dismissed those at hand, and said to Yan: \"Young lady, if you will report something for me, I also wish to repay the young lady—may I?", idiomatic: "\" Yan reported as told to Xian; Xian conceived a plan, dismissed attendants, and said to Yan, \"Young lady, if you will do something for me, I also wish to repay you—will you?" },
  { zh: "」衍曰：「夫人所言，何等不可者！", literal: "\" Yan said: \"Whatever the lady says—what could not be done!", idiomatic: "\" Yan said, \"Whatever my lady says—what could not be done!" },
  { zh: "」顯曰：「將軍素愛小女成君，欲奇貴之，願以累少夫。", literal: "\" Xian said: \"The General has long loved my younger daughter Chengjun and wishes to exalt her extraordinarily; I wish to entrust this to the young lady.", idiomatic: "\" Xian said, \"The General has long loved my younger daughter Chengjun and wishes to exalt her extraordinarily; I wish to entrust this to you." },
  { zh: "」衍曰：「何謂邪？", literal: "\" Yan said: \"What does this mean?", idiomatic: "\" Yan said, \"What do you mean?" },
  { zh: "」顯曰：「婦人免乳，大故，十死一生。", literal: "\" Xian said: \"When a woman completes childbirth, it is a great matter—nine deaths to one life.", idiomatic: "\" Xian said, \"Childbirth is a grave matter—nine deaths to one life." },
  { zh: "今皇后當免身，可因投毒藥去也，成君即為皇后矣。", literal: "Now the empress is about to complete childbirth; you may take the opportunity to administer poison and remove her—Chengjun will then be empress.", idiomatic: "Now the empress is about to give birth; you may take the opportunity to poison her—Chengjun will then be empress." },
  { zh: "如蒙力，事成，富貴與少夫共之。", literal: "If you grant your strength and the affair succeeds, wealth and honor will be shared with the young lady.", idiomatic: "If you lend your strength and it succeeds, wealth and honor will be shared with you." },
  { zh: "」衍曰：「藥雜治，常先嘗，安可？", literal: "\" Yan said: \"Medicines are mixed and treated—the physician always tastes them first; how could it be done?", idiomatic: "\" Yan said, \"Medicines are compounded and the physician always tastes them first—how could it be done?" },
  { zh: "」顯曰：「在少夫為之耳。", literal: "\" Xian said: \"It lies with the young lady to do it.", idiomatic: "\" Xian said, \"That is for you to do." },
  { zh: "將軍領天下，誰敢言者！", literal: "The General commands all under Heaven—who would dare speak!", idiomatic: "The General commands the realm—who would dare speak!" },
  { zh: "緩急相護，但恐少夫無意耳。", literal: "In urgency and ease we protect one another—I only fear the young lady has no intent.", idiomatic: "In urgency and ease we protect one another—I only fear you lack the will." },
  { zh: "」衍良久曰：「願盡力！", literal: "\" After a long while Yan said: \"I am willing to exert all my strength!", idiomatic: "\" After a long while Yan said, \"I will do all I can!" },
  { zh: "」即搗附子，賫入長定宮。", literal: "\" She immediately pounded aconite and carried it into Changding Palace.", idiomatic: "\" She pounded aconite and carried it into Changding Palace." },
  { zh: "皇后免身後，衍取附子併合太醫大丸以飲皇后，有頃，曰：「我頭岑岑也，藥中得無有毒？", literal: "After the empress completed childbirth, Yan took the aconite, mixed it into the Grand Physician's large pill, and had the empress drink it; after a moment she said: \"My head is dizzy—is there perhaps poison in the medicine?", idiomatic: "After the empress gave birth, Yan mixed aconite into the Grand Physician's large pill and had her drink it; presently she said, \"My head is swimming—could there be poison in the medicine?" },
  { zh: "」對曰：「無有。", literal: "\" The reply was: \"There is none.", idiomatic: "\" The reply was, \"There is none." },
  { zh: "」遂加煩懣，崩。", literal: "\" She thereupon grew more distressed and vexed and died.", idiomatic: "\" She grew more distressed and died." },
  { zh: "衍出，過見顯，相勞問，亦未敢重謝衍。", literal: "Yan went out, passed and saw Xian, exchanged greetings, yet did not dare heavily thank Yan.", idiomatic: "Yan went out, saw Xian on the way, exchanged greetings, yet did not dare thank her effusively." },
  { zh: "後人有上書告諸醫侍疾無狀者，皆收繫詔獄，劾不道。", literal: "Later someone memorialized accusing the physicians who attended the illness of misconduct; all were arrested and imprisoned in the edict prison, impeached for impiety.", idiomatic: "Later someone memorialized accusing the attending physicians of misconduct; all were arrested in the edict prison and impeached for impiety." },
  { zh: "顯恐急，即以狀具語光，因曰：「既失計為之，無令吏急衍！", literal: "Xian, fearful and urgent, fully told Guang the circumstances, saying: \"Having erred in doing this, do not let the officials press Yan!", idiomatic: "Xian, in fear, fully told Guang the circumstances and said, \"Having erred in this, do not let the officials press Yan!" },
  { zh: "」光大驚，欲自發舉，不忍，猶與。", literal: "\" Guang was greatly shocked, wished to report it himself, could not bear to, and still hesitated.", idiomatic: "\" Guang was greatly shocked, wished to report it himself but could not bear to, and still wavered." },
  { zh: "會奏上，光署衍勿論。", literal: "When the memorial was submitted, Guang endorsed that Yan not be prosecuted.", idiomatic: "When the memorial was submitted, Guang endorsed that Yan not be prosecuted." },
  { zh: "顯因勸光內其女入宮。", literal: "Xian thereupon urged Guang to bring her daughter into the palace.", idiomatic: "Xian urged Guang to bring her daughter into the palace." },
  { zh: "----2戊辰，五將軍發長安。", literal: "----2 On wuchen the five generals set out from Chang'an.", idiomatic: "----2 On wuchen the five generals set out from Chang'an." },
  { zh: "匈奴聞漢兵大出，老弱奔走，驅畜產遠遁逃，是以五將少所得。", literal: "The Xiongnu heard Han troops were coming out in force; the old and weak fled in haste, driving livestock far off in escape—thus the five generals gained little.", idiomatic: "The Xiongnu heard Han troops were coming out in force; the old and weak fled, driving livestock far off—thus the five generals gained little." },
  { zh: "夏，五月，軍罷。", literal: "In summer, the fifth month, the armies were dismissed.", idiomatic: "In summer, the fifth month, the armies were dismissed." },
  { zh: "度遼將軍出塞千二百餘里，至蒲離候水，斬首、捕虜七百餘級；", literal: "General Crossing the Liao went beyond the passes more than twelve hundred li, reached the Puli Marquis's Water, and cut heads and captured prisoners more than seven hundred;", idiomatic: "General Crossing the Liao went beyond the passes more than twelve hundred li to Puli Marquis's Water and cut more than seven hundred heads and captives;" },
  { zh: "前將軍出塞千二百餘里，至烏員，斬首、捕虜百餘級；", literal: "the Forward General went beyond the passes more than twelve hundred li, reached Wuyuan, and cut heads and captured prisoners more than one hundred;", idiomatic: "the Forward General went more than twelve hundred li beyond the passes to Wuyuan and cut more than one hundred heads and captives;" },
  { zh: "蒲類將軍出塞千八百餘里，西至候山，斬首、捕虜，得單于使者蒲陰王以下三百餘級。", literal: "the General of Pu Lei went beyond the passes more than eighteen hundred li, west to Hou Mountain, cut heads and captured prisoners, obtaining the Chanyu's envoy Pu Yin Wang and below—more than three hundred;", idiomatic: "the General of Pu Lei went more than eighteen hundred li beyond the passes west to Hou Mountain, cut heads and captives, and took the chanyu's envoy Pu Yin Wang and others—more than three hundred;" },
  { zh: "聞虜已引去，皆不至期還。", literal: "Hearing the barbarians had already withdrawn, all failed to return by the appointed date.", idiomatic: "Hearing the enemy had withdrawn, all failed to return by the appointed date." },
  { zh: "天子薄其過，寬而不罪。", literal: "The Son of Heaven regarded their offenses lightly and was lenient without punishing them.", idiomatic: "The emperor regarded their offenses lightly and did not punish them." },
  { zh: "祁連將軍出塞千六百里，至雞秩山，斬首、捕虜十九級。", literal: "General of Qilian went beyond the passes sixteen hundred li, reached Jizhi Mountain, and cut heads and captured prisoners nineteen.", idiomatic: "General of Qilian went sixteen hundred li beyond the passes to Jizhi Mountain and cut nineteen heads and captives." },
  { zh: "逢漢使匈奴還者冉弘等，言雞秩山西有虜眾，祁連即戒弘，使言無虜，欲還兵。", literal: "He met Han envoys returning from the Xiongnu, Ran Hong and others, who said west of Jizhi Mountain there were barbarian masses; Qilian immediately warned Hong to say there were no barbarians, wishing to withdraw the army.", idiomatic: "He met Han envoys returning from the Xiongnu, Ran Hong and others, who said there were enemy forces west of Jizhi Mountain; Qilian warned Hong to say there were none, wishing to withdraw." },
  { zh: "御史屬公孫益壽諫，以為主可。", literal: "Secretary of the Censorate Gongsun Yishou remonstrated, thinking the commander could do it.", idiomatic: "Secretary of the Censorate Gongsun Yishou remonstrated that the commander should advance." },
  { zh: "祁連不聽，遂引兵還。", literal: "Qilian did not listen and thereupon withdrew the army.", idiomatic: "Qilian did not listen and withdrew the army." },
  { zh: "虎牙將軍出塞八百餘里，至丹餘吾水上，即止兵不進，斬首、捕虜千九百餘級，引兵還。", literal: "General of Tiger's Teeth went beyond the passes more than eight hundred li, reached the Dan Yuyu River, thereupon halted the army and did not advance, cut heads and captured prisoners more than nineteen hundred, and withdrew the army.", idiomatic: "General of Tiger's Teeth went more than eight hundred li beyond the passes to the Dan Yuyu River, halted without advancing, cut more than nineteen hundred heads and captives, and withdrew." },
  { zh: "上以虎牙將軍不至期，詐增鹵獲，而祁連知虜在前，逗遛不進，皆下吏，自殺。", literal: "The emperor, because General of Tiger's Teeth failed to arrive by the date and falsely inflated captive gains, and Qilian knew the barbarians were ahead yet hesitated and did not advance, sent both to the officials; they committed suicide.", idiomatic: "The emperor, because General of Tiger's Teeth failed to arrive on time and falsely inflated captures, and Qilian knew the enemy was ahead yet hesitated and did not advance, sent both to the officials; they committed suicide." },
  { zh: "擢公孫益壽為侍御史。", literal: "Gongsun Yishou was promoted to Attending Censor.", idiomatic: "Gongsun Yishou was promoted to Attending Censor." },
  { zh: "烏孫昆彌自將五萬騎與校尉常惠從西方入，至右谷蠡王庭，獲單于父行及嫂、居次、名王、犁汙都尉、千長、騎將以下四萬級，馬、牛、羊、驢、橐佗七十餘萬頭。", literal: "The Wusun kunmi personally led fifty thousand horsemen with Colonel Chang Hui entering from the west to the Right Guli King's court, obtaining the chanyu's father's generation and elder sister-in-law, younger sisters, named kings, Liyu colonels, thousand-chiefs, cavalry generals and below—forty thousand in rank, and horses, cattle, sheep, donkeys, and camels more than seven hundred thousand head.", idiomatic: "The Wusun kunmi personally led fifty thousand horsemen with Colonel Chang Hui, entering from the west to the Right Guli King's court, capturing the chanyu's father's generation, sisters-in-law, younger sisters, named kings, Liyu colonels, thousand-chiefs, cavalry generals and below—forty thousand in rank—and more than seven hundred thousand horses, cattle, sheep, donkeys, and camels." },
  { zh: "烏孫皆自取所虜獲。", literal: "The Wusun all took for themselves what they had captured.", idiomatic: "The Wusun kept all they had captured." },
  { zh: "上以五將皆無功，獨惠奉使克獲，封惠為長羅侯。", literal: "The emperor, because the five generals all had no achievement while Hui alone on his mission succeeded in capture, enfeoffed Hui as Marquis of Changluo.", idiomatic: "Because the five generals all achieved nothing while Hui alone on his mission succeeded, the emperor enfeoffed Hui as Marquis of Changluo." },
  { zh: "然匈奴民眾傷而去者及畜產遠移死亡，不可勝數。", literal: "Yet the Xiongnu's people wounded and departed and livestock moved far off and died were beyond counting.", idiomatic: "Yet Xiongnu wounded and displaced people and livestock moved far off and died in numbers beyond counting." },
  { zh: "於是匈奴遂衰耗，怨烏孫。", literal: "Thereupon the Xiongnu declined and were depleted and resented Wusun.", idiomatic: "Thereupon the Xiongnu declined and resented Wusun." },
  { zh: "上復遣常惠持金幣還賜烏孫貴人有功者。", literal: "The emperor again dispatched Chang Hui bearing gold and coins to return and bestow on Wusun nobles who had merit.", idiomatic: "The emperor again dispatched Chang Hui with gold and coins to reward meritorious Wusun nobles." },
  { zh: "惠因奏請龜茲國嘗殺校尉賴丹，未伏誅，請便道擊之。", literal: "Hui thereupon memorialized requesting that Kucha had once killed Colonel Lai Dan and had not submitted to execution, and asked to strike them by a convenient route.", idiomatic: "Hui thereupon memorialized that Kucha had once killed Colonel Lai Dan without having submitted to punishment, and asked to strike them by a convenient route." },
  { zh: "帝不許。", literal: "The emperor did not permit it.", idiomatic: "The emperor did not permit it." },
  { zh: "大將軍霍光風惠以便宜從事。", literal: "Grand General Huo Guang hinted to Hui that he might act as expedience required.", idiomatic: "Grand General Huo Guang hinted to Hui that he might act at his discretion." },
  { zh: "惠與吏士五百人俱至烏孫，還，過，發西國兵二萬人，令副使發龜茲東國二萬人，烏孫兵七千人，從三面攻龜茲。", literal: "Hui, with five hundred clerks and soldiers, together reached Wusun; on the return, passing through, he raised twenty thousand troops of the western states, ordered the deputy envoy to raise twenty thousand of Kucha's eastern states, and seven thousand Wusun troops, and attacked Kucha from three sides.", idiomatic: "Hui, with five hundred clerks and soldiers, reached Wusun; on the return march he raised twenty thousand troops of the western states, had the deputy envoy raise twenty thousand from Kucha's eastern dependencies and seven thousand Wusun troops, and attacked Kucha from three sides." },
  { zh: "兵未合，先遣人責其王以前殺漢使狀。", literal: "Before the armies joined, he first sent someone to reproach the king for the earlier killing of Han envoys.", idiomatic: "Before the armies converged, he first sent someone to reproach the king for having killed Han envoys." },
  { zh: "王謝曰：「乃我先王時為貴人姑翼所誤耳，我無罪。", literal: "The king apologized, saying: \"It was only in my former king's time that the noble Gu Yi misled us—I am without guilt.", idiomatic: "The king apologized, saying, \"It was only in my former king's time that the noble Gu Yi misled us—I am guiltless." },
  { zh: "」惠曰：「即如此，縛姑翼來，吾置王。", literal: "\" Hui said: \"If it is so, bind Gu Yi and bring him—I will install you as king.", idiomatic: "\" Hui said, \"If so, bind Gu Yi and bring him—I will install you as king." },
  { zh: "」王執姑翼詣惠，惠斬之而還。", literal: "\" The king seized Gu Yi and presented him to Hui; Hui beheaded him and returned.", idiomatic: "\" The king seized Gu Yi and presented him to Hui; Hui beheaded him and returned." },
  { zh: "----3大旱。", literal: "----3 Great drought.", idiomatic: "----3 There was a great drought." },
  { zh: "----4六月，己丑，陽平節侯蔡義薨。", literal: "----4 In the sixth month, on jichou, Marquis Jie of Yangping Cai Yi died.", idiomatic: "----4 In the sixth month, on jichou, Marquis Jie of Yangping Cai Yi died." },
  { zh: "----5甲辰，長信少府韋賢為丞相。", literal: "----5 On jiachen, Director of Changxin Household Wei Xian became Chancellor.", idiomatic: "----5 On jiachen, Director of Changxin Household Wei Xian became chancellor." },
  { zh: "----6大司農魏相為御史大夫。", literal: "----6 Grand Minister of Agriculture Wei Xiang became Censor-in-Chief.", idiomatic: "----6 Grand Minister of Agriculture Wei Xiang became censor-in-chief." },
  { zh: "----7冬，匈奴單于自將數萬騎擊烏孫，頗得老弱。", literal: "----7 In winter the Xiongnu chanyu personally led tens of thousands of horsemen to strike Wusun and took many of the old and weak.", idiomatic: "----7 In winter the Xiongnu chanyu personally led tens of thousands of horsemen against Wusun and captured many of the old and weak." },
  { zh: "欲還，會天大雨雪，一日深丈餘，人民、畜產凍死，還者不能什一。", literal: "Wishing to return, they encountered heaven's great rain and snow; in one day it was more than a zhang deep; people and livestock froze to death, and of those returning not one in ten.", idiomatic: "As they wished to return, heavy rain and snow fell; in one day the snow was more than a zhang deep; people and livestock froze to death, and fewer than one in ten of those who set out returned." },
  { zh: "於是丁令乘弱攻其北，烏桓入其東，烏孫擊其西，凡三國所殺數萬級，馬數萬匹，牛羊甚眾；", literal: "Thereupon the Dingling, taking advantage of weakness, struck their north; the Wuhuan entered their east; Wusun struck their west—in all the three states killed tens of thousands, tens of thousands of horses, and very many cattle and sheep;", idiomatic: "Thereupon the Dingling, seizing their weakness, struck from the north; the Wuhuan entered from the east; Wusun struck from the west—the three states together killed tens of thousands, seized tens of thousands of horses, and very many cattle and sheep;" },
  { zh: "又重以餓死，人民死者什三，畜產什五。", literal: "and moreover, with starvation added, of the people three-tenths died and of livestock five-tenths.", idiomatic: "and with starvation added, three-tenths of the people and five-tenths of the livestock perished." },
  { zh: "匈奴大虛弱，諸國羈屬者皆瓦解，攻盜不能理。", literal: "The Xiongnu were greatly weakened; all states bound in submission dissolved, and raids and theft could not be controlled.", idiomatic: "The Xiongnu were greatly weakened; all subordinate states broke away, and raids and banditry could not be controlled." },
  { zh: "其後漢出三千餘騎為三道，並入匈奴，捕虜得數千人還；", literal: "Afterward Han sent out more than three thousand horsemen in three columns, together entering the Xiongnu, capturing prisoners numbering several thousand and returning;", idiomatic: "Afterward Han sent out more than three thousand horsemen in three columns into Xiongnu territory, captured several thousand prisoners, and returned;" },
  { zh: "匈奴終不敢取當，滋欲鄉和親，而邊境少事矣。", literal: "the Xiongnu in the end did not dare meet them in battle, increasingly wished to turn toward peace by marriage, and border affairs grew few.", idiomatic: "the Xiongnu in the end did not dare meet them in battle, increasingly wished to seek peace through marriage, and border affairs grew quiet." },
  { zh: "----8是歲，穎川太守趙廣漢為京兆尹。", literal: "----8 That year, Governor of Yingchuan Zhao Guanghan became Metropolitan Magistrate of Jingzhao.", idiomatic: "----8 That year, Governor of Yingchuan Zhao Guanghan became metropolitan magistrate of Jingzhao." },
  { zh: "穎川俗，豪桀相朋黨。", literal: "Yingchuan custom: powerful men formed factions with one another.", idiomatic: "In Yingchuan custom, powerful men formed factions with one another." },
  { zh: "廣漢為缿筒，受吏民投書，使相告訐，於是更相怨咎，奸黨散落，盜賊不敢發。", literal: "Guanghan made letter-boxes, received writings cast in by clerks and people, and had them inform on one another; thereupon they turned on one another in blame, wicked factions scattered, and bandits did not dare act.", idiomatic: "Guanghan set up letter-boxes, received anonymous writings from clerks and commoners, and had them inform on one another; factions turned on one another, wicked cliques scattered, and bandits did not dare act." },
  { zh: "匈奴降者言匈奴中皆聞廣漢名，由是入為京兆尹。", literal: "Xiongnu who surrendered said that within the Xiongnu all had heard Guanghan's name; on this account he entered office as Metropolitan Magistrate.", idiomatic: "Surrendered Xiongnu said that throughout the Xiongnu all had heard Guanghan's name; on this account he was appointed metropolitan magistrate." },
  { zh: "廣漢遇吏，殷勤甚備，事推功善，歸之於下，行之發於至誠，吏咸願為用，僵仆無所避。", literal: "Guanghan in meeting clerks was most attentive and thorough; in affairs he pushed merit and goodness down to subordinates; his conduct arose from utmost sincerity; clerks all wished to serve him, and even if they fell stiff they did not avoid duty.", idiomatic: "Guanghan treated his clerks with the utmost care and attention; he credited subordinates with merit and goodness; his conduct arose from utmost sincerity; clerks all wished to serve him, and even if they fell exhausted they did not shirk duty." },
  { zh: "廣漢聰明，皆知其能之所宜，盡力與否；", literal: "Guanghan was perceptive and clear; he all knew what each man's ability suited and whether he exerted his strength or not;", idiomatic: "Guanghan was perceptive; he knew what each man's ability suited and whether he exerted his full strength;" },
  { zh: "其或負者。", literal: "those who failed in duty.", idiomatic: "those who failed in duty." },
  { zh: "輒收捕之，無所逃；", literal: "he immediately arrested them, with nowhere to escape;", idiomatic: "he immediately arrested them, with nowhere to escape;" },
  { zh: "案之，罪立具，即時伏辜。", literal: "investigated the case, the offense was immediately established, and at once they submitted to punishment.", idiomatic: "investigated the case, the offense was immediately established, and at once they submitted to punishment." },
  { zh: "尤善為鉤距以得事情，-{閭里}-銖兩之奸皆知之。", literal: "He was especially skilled at hook-and-lever methods to obtain the facts of affairs; -{閭里}- petty frauds of a cash or two he all knew.", idiomatic: "He was especially skilled at investigative accounting to uncover facts; -{閭里}- petty frauds down to a cash or two he all knew." },
  { zh: "長安少年數人會窮-{里}-空舍，謀共劫人；", literal: "Several youths of Chang'an met in a poor -{里}- empty house and plotted together to rob people;", idiomatic: "Several youths of Chang'an met in a poor -{里}- empty house and plotted to rob people together;" },
  { zh: "坐語未訖，廣漢使吏捕治，具服。", literal: "seated in talk not yet finished, Guanghan sent clerks to arrest and try them, and they fully confessed.", idiomatic: "before their talk was finished, Guanghan sent clerks to arrest and try them, and they fully confessed." },
  { zh: "其發奸擿伏如神。", literal: "His exposing wickedness and plucking out hidden matters was like a spirit's.", idiomatic: "His exposing crime and uncovering hidden plots was uncanny." },
  { zh: "京兆政清，吏民稱之不容口。", literal: "Jingzhao's government was clear; clerks and people praised him without room left in the mouth.", idiomatic: "Jingzhao's government was clear; clerks and people praised him without end." },
  { zh: "長老傳以為自漢興，治京兆者莫能及。", literal: "The elders transmitted that since Han's rise, none who governed Jingzhao could match him.", idiomatic: "The elders transmitted that since Han's rise, none who governed Jingzhao could match him." },
  { zh: "1春，三月，乙卯，立霍光女為皇后，赦天下。", literal: "1 In spring, the third month, on yimao, Huo Guang's daughter was established as empress; there was an amnesty for all under Heaven.", idiomatic: "1 In spring, the third month, on yimao, Huo Guang's daughter was established as empress and there was an amnesty for all under Heaven." },
  { zh: "初，-{許后}-起微賤，登至尊日淺，從官車服甚節儉。", literal: "Initially -{許后}- rose from humble standing; days on the supreme seat were few; attendants' carriages and dress were very frugal.", idiomatic: "Initially -{許后}- rose from humble origins; her days on the throne were few; attendants' carriages and dress were very frugal." },
  { zh: "及-{霍后}-立，輿駕、侍從益盛，賞賜官屬以千萬計，與-{許后}-時縣絕矣。", literal: "When -{霍后}- was established, imperial carriages and attendants grew ever grander; rewards to official subordinates were reckoned in tens of millions—utterly unlike the time of -{許后}-.", idiomatic: "When -{霍后}- was established, imperial carriages and attendants grew ever grander; rewards to officials were reckoned in tens of millions—utterly unlike the time of -{許后}-." },
  { zh: "----2夏，四月，壬寅，郡國四十九同日地震，或山崩，壞城郭、室屋，殺六千餘人。", literal: "----2 In summer, the fourth month, on renyin, forty-nine commanderies and states on the same day had earthquakes; some mountains collapsed, city walls and houses were ruined, and more than six thousand were killed.", idiomatic: "----2 In summer, the fourth month, on renyin, forty-nine commanderies and states had earthquakes on the same day; some mountains collapsed, city walls and houses were ruined, and more than six thousand were killed." },
  { zh: "北海、琅邪壞祖宗廟。", literal: "Beihai and Langye had their ancestral temples ruined.", idiomatic: "The ancestral temples of Beihai and Langye were ruined." },
  { zh: "詔丞相、御史與列侯、中二千石博問經學之士，有以應變，毋有所諱。", literal: "An edict ordered the Chancellor, Censor, ranked marquises, and the two-thousand-bushel officials broadly to question scholars of the classics, that there be means to respond to change, and that nothing be concealed.", idiomatic: "An edict ordered the chancellor, censor, marquises, and two-thousand-bushel officials broadly to consult scholars of the classics for means to respond to the calamity, without concealment." },
  { zh: "令三輔、太常、內郡國舉賢良方正各一人。", literal: "It ordered the Three Metropolises, Grand Master of Ceremonies, and inner commanderies and states each to recommend one worthy and upright.", idiomatic: "It ordered the Three Metropolises, Grand Master of Ceremonies, and inner commanderies and states each to recommend one worthy and upright candidate." },
  { zh: "大赦天下。", literal: "There was a great amnesty for all under Heaven.", idiomatic: "There was a great amnesty for all under Heaven." },
  { zh: "上素服，避正殿五日。", literal: "The emperor wore plain dress and avoided the main hall for five days.", idiomatic: "The emperor wore plain dress and avoided the main hall for five days." },
  { zh: "釋夏侯勝、黃霸，以勝為諫大夫、給事中，霸為揚州刺史。", literal: "He released Xiahou Sheng and Huang Ba, making Sheng Remonstrance Grandee and Attendant Within the Gates, and Ba Governor of Yangzhou.", idiomatic: "He released Xiahou Sheng and Huang Ba, making Sheng remonstrance grandee and attendant within the gates, and Ba governor of Yangzhou." },
  { zh: "勝為人，質樸守正，簡易無威儀，或時謂上為君，誤相字於前；", literal: "Sheng as a man was plain and upheld rectitude, simple and easy without imposing deportment; sometimes he called the emperor \"lord\" and mistakenly used familiar terms before him;", idiomatic: "Sheng was plain and upheld rectitude, simple and without imposing deportment; sometimes he called the emperor \"lord\" and mistakenly used familiar terms in his presence;" },
  { zh: "上亦以是親信之。", literal: "the emperor also on this account was close to and trusted him.", idiomatic: "the emperor also for this reason was close to and trusted him." },
  { zh: "嘗見，出道上語，上聞而讓勝，勝曰：「陛下所言善，臣故揚之。", literal: "Once when he had an audience, he went out and spoke the emperor's words on the road; the emperor heard and reproached Sheng; Sheng said: \"What Your Majesty said was good—your servant therefore spread it.", idiomatic: "Once after an audience he repeated the emperor's words on the road; the emperor heard and reproached Sheng; Sheng said, \"What Your Majesty said was good—your servant therefore spread it." },
  { zh: "堯言佈於天下，至今見誦。", literal: "Yao's words were spread through all under Heaven and to this day are seen recited.", idiomatic: "Yao's words were spread through all under Heaven and are recited to this day." },
  { zh: "臣以為可傳，故傳耳。", literal: "Your servant thought they could be transmitted, and therefore transmitted them.", idiomatic: "Your servant thought they should be transmitted, and therefore transmitted them." },
  { zh: "」朝廷每有大議，上知勝素直，謂曰：「先生建正言，無懲前事！", literal: "\" Whenever the court had great deliberations, the emperor, knowing Sheng was by nature upright, said to him: \"Master, set forth correct words—do not be chastened by former affairs!", idiomatic: "\" Whenever the court had great deliberations, the emperor, knowing Sheng was by nature upright, said to him, \"Master, set forth correct words—do not be chastened by former affairs!" },
  { zh: "」勝復為長信少府，後遷太子太傅。", literal: "\" Sheng was again made Director of Changxin Household and later transferred to Grand Tutor of the Heir Apparent.", idiomatic: "\" Sheng was again made director of Changxin Household and later transferred to grand tutor of the heir apparent." },
  { zh: "年九十卒，太后賜錢二百萬，為勝素服五日，以報師傅之恩。", literal: "At age ninety he died; the empress dowager bestowed two million cash, wore plain dress for Sheng for five days, to repay the grace of a teacher.", idiomatic: "He died at age ninety; the empress dowager bestowed two million cash and wore plain dress for him for five days to repay a teacher's grace." },
  { zh: "儒者以為榮。", literal: "Confucians took this as glory.", idiomatic: "Confucians took this as an honor." },
  { zh: "----3五月，鳳皇集北海安丘、-{淳于}-。", literal: "----3 In the fifth month, phoenixes gathered at Anqiu in Beihai and -{淳于}-.", idiomatic: "----3 In the fifth month, phoenixes gathered at Anqiu in Beihai and -{淳于}-." },
  { zh: "----4廣川王去坐殺其師及姬妾十餘人，或銷鉛錫灌口中，或支解，並毒藥煮之，令糜盡，廢徙上庸；", literal: "----4 Prince Qu of Guangchuan was charged with killing his tutor and more than ten concubines—some he melted lead and tin and poured into their mouths, some he dismembered, and together he boiled them with poison medicine until they were reduced to paste; he was deposed and moved to Shangyong;", idiomatic: "----4 Prince Qu of Guangchuan was charged with killing his tutor and more than ten concubines—some he poured molten lead and tin into their mouths, some he dismembered, and he boiled them together with poison until they were reduced to paste; he was deposed and moved to Shangyong;" },
  { zh: "自殺。", literal: "he killed himself.", idiomatic: "he killed himself." },
  { zh: "1春，正月，有星孛於西方。", literal: "1 In spring, the first month, a broom star appeared in the west.", idiomatic: "1 In spring, the first month, a comet appeared in the west." },
  { zh: "----2楚王延壽以廣陵王胥，武帝子，天下有變，必得立，陰附肋之，為其後母弟趙何齊取廣陵王女為妻，因使何齊奉書遺廣陵王曰：「願長耳目，毋後人有天下！", literal: "----2 King Shou of Chu, because the Prince of Guangling Xu was Emperor Wu's son and if the realm had change would surely be established, secretly attached himself and aided him; for his younger brother by a different mother Zhao Heqi he took the Prince of Guangling's daughter as wife, and thereby had Heqi present a letter to the Prince of Guangling, saying: \"I wish to extend my ears and eyes—do not let later men have all under Heaven!", idiomatic: "----2 King Shou of Chu, because Prince Xu of Guangling was Emperor Wu's son and if the realm changed would surely be enthroned, secretly attached himself and aided him; for his younger half-brother Zhao Heqi he took the Prince of Guangling's daughter as wife and had Heqi present a letter to the prince, saying, \"I wish to extend my ears and eyes—do not let later men possess all under Heaven!" },
  { zh: "」何齊父長年上書告之，事下有司考驗，辭服。", literal: "\" Heqi's father Changnian memorialized to report it; the affair was sent down to the responsible offices for examination; the confession was accepted.", idiomatic: "\" Heqi's father Changnian memorialized to report it; the affair was sent to the responsible offices for examination and the confession was accepted." },
  { zh: "冬，十一月，延壽自殺。", literal: "In winter, the eleventh month, Shou killed himself.", idiomatic: "In winter, the eleventh month, Shou killed himself." },
  { zh: "胥勿治。", literal: "Xu was not prosecuted.", idiomatic: "Xu was not prosecuted." },
  { zh: "----3十二月，癸亥晦，日有食之。", literal: "----3 In the twelfth month, on guihai the last day of the month, there was a solar eclipse.", idiomatic: "----3 In the twelfth month, on guihai the last day of the month, there was a solar eclipse." },
  { zh: "----4是歲，-{于定國}-為廷尉。", literal: "----4 That year -{于定國}- became Director of Justice.", idiomatic: "----4 That year -{于定國}- became director of justice." },
  { zh: "定國決疑平法，務在哀鰥寡，罪疑從輕，加審慎之心。", literal: "Dingguo in deciding doubtful cases balanced the law, striving to pity widowers and widows, treating doubtful guilt with leniency, and adding a mind of careful scrutiny.", idiomatic: "Dingguo in deciding doubtful cases balanced the law, striving to pity widowers and widows, treating doubtful guilt with leniency, and exercising careful scrutiny." },
  { zh: "朝廷稱之曰：「張釋之為廷尉，天下無冤民。", literal: "The court praised him, saying: \"When Zhang Shizhi was Director of Justice, all under Heaven had no wrongly accused people.", idiomatic: "The court praised him, saying, \"When Zhang Shizhi was director of justice, all under Heaven had no wrongly accused people." },
  { zh: "-{于定國}-為廷尉，民自以不冤。", literal: "-{于定國}- as Director of Justice—the people by themselves felt they were not wronged.", idiomatic: "-{于定國}- as director of justice—the people by themselves felt they were not wronged." },
  { zh: "1春，霍光病篤。", literal: "1 In spring, Huo Guang's illness was grave.", idiomatic: "1 In spring, Huo Guang's illness was grave." },
  { zh: "車駕自臨問，上為之涕泣。", literal: "The imperial carriage personally came to inquire; the emperor wept tears for him.", idiomatic: "The emperor personally came to inquire; he wept for him." },
  { zh: "光上書謝恩，願分國邑三千戶以封兄孫奉車都尉山為列侯，奉兄去病祀。", literal: "Guang submitted a memorial thanking for grace, wishing to divide three thousand households of his state fief to enfeoff his elder brother's grandson Palace Coachman Colonel Shan as a ranked marquis to tend the sacrifices to his brother Qubing.", idiomatic: "Guang submitted a memorial thanking for grace, wishing to divide three thousand households of his fief to enfeoff his elder brother's grandson Palace Coachman Colonel Shan as a marquis to tend the sacrifices to his brother Qubing." },
  { zh: "即日，拜光子禹為右將軍。", literal: "That same day, Guang's son Yu was appointed Right General.", idiomatic: "That same day, Guang's son Yu was appointed right general." },
  { zh: "三月，庚午，光薨。", literal: "In the third month, on gengwu, Guang died.", idiomatic: "In the third month, on gengwu, Guang died." },
  { zh: "上及皇太后親臨光喪，中二千石治塚，賜梓宮、葬具皆如乘輿制度，謚曰宣成侯。", literal: "The emperor and empress dowager personally attended Guang's mourning; two-thousand-bushel officials oversaw the tomb; they bestowed a catalpa coffin and burial goods all according to the imperial carriage's regulations; his posthumous title was Marquis Xuancheng.", idiomatic: "The emperor and empress dowager personally attended Guang's mourning; two-thousand-bushel officials oversaw the tomb; they bestowed a catalpa coffin and burial goods all according to imperial regulations; his posthumous title was Marquis Xuancheng." },
  { zh: "發三河卒穿覆土，置園邑三百家，長、丞奉守；", literal: "They raised Three Rivers conscripts to dig and cover the earth, established a park settlement of three hundred households, with a chief and assistant to tend and guard it;", idiomatic: "They raised Three Rivers conscripts to dig and cover the tomb, established a park settlement of three hundred households with a chief and assistant to tend and guard it;" },
  { zh: "下詔復其後世，疇其爵邑，世世無有所與。", literal: "an edict was issued to restore his later generations, grant his noble fief in perpetuity, generation after generation without any levy.", idiomatic: "an edict was issued to restore his later generations, grant his noble fief in perpetuity, generation after generation without any levy." },
  { zh: "御史大夫魏相上封事曰：「國家新失大將軍，宜顯明功臣以填籓國，毋空大位，以塞爭權。", literal: "Censor-in-Chief Wei Xiang submitted a sealed memorial, saying: \"The state has newly lost the Grand General; it is fitting to display and clarify meritorious ministers to fill the feudal states, not leave great offices empty, to block contention for power.", idiomatic: "Censor-in-Chief Wei Xiang submitted a sealed memorial: \"The state has newly lost the grand general; it is fitting to display meritorious ministers to fill the feudal states, not leave great offices empty, to block contention for power." },
  { zh: "宜以車騎將軍安世為大將軍，毋令領光祿勳事；", literal: "It is fitting to make General of Chariots and Cavalry Anshi Grand General and not let him oversee Director of the Palace's affairs;", idiomatic: "It is fitting to make General of Chariots and Cavalry Anshi grand general and not let him oversee the director of the palace's affairs;" },
  { zh: "以其子延壽為光祿勳。", literal: "make his son Shou Director of the Palace.", idiomatic: "make his son Shou director of the palace." },
  { zh: "」上亦欲用之。", literal: "\" The emperor also wished to use him thus.", idiomatic: "\" The emperor also wished to use him thus." },
  { zh: "夏，四月，戊申，以安世為大司馬、車騎將軍，領尚書事。", literal: "In summer, the fourth month, on wushen, Anshi was made Grand Marshal and General of Chariots and Cavalry, overseeing Secretariat affairs.", idiomatic: "In summer, the fourth month, on wushen, Anshi was made grand marshal and general of chariots and cavalry, overseeing secretariat affairs." },
  { zh: "----2鳳皇集魯，群鳥從之。", literal: "----2 Phoenixes gathered in Lu; flocks of birds followed them.", idiomatic: "----2 Phoenixes gathered in Lu; flocks of birds followed them." },
  { zh: "大赦天下。", literal: "There was a great amnesty for all under Heaven.", idiomatic: "There was a great amnesty for all under Heaven." },
  { zh: "----3上思報大將軍德，乃封光兄孫山為樂平侯，使以奉車都尉領尚書事。", literal: "----3 The emperor, thinking to repay the Grand General's virtue, thereupon enfeoffed Guang's elder brother's grandson Shan as Marquis of Le Ping and had him as Palace Coachman Colonel oversee Secretariat affairs.", idiomatic: "----3 The emperor, thinking to repay the grand general's virtue, enfeoffed Guang's elder brother's grandson Shan as Marquis of Le Ping and had him as palace coachman colonel oversee secretariat affairs." },
  { zh: "魏相因昌成君許廣漢奏封事，言：「《春秋》譏世卿，惡宋三世為大夫及魯季孫之專權，皆危亂國家。", literal: "Wei Xiang, through Lord of Changcheng Xu Guanghan, submitted a sealed memorial, saying: \"The Spring and Autumn Annals ridicule hereditary ministers, detest Song's three generations as grandees and the Lu Ji Sun clan's monopolization of power—all endangered and disordered the state.", idiomatic: "Wei Xiang, through Lord of Changcheng Xu Guanghan, submitted a sealed memorial: \"The Spring and Autumn Annals ridicule hereditary ministers, detest Song's three generations as grandees and the Lu Ji Sun clan's monopoly of power—all endangered the state." },
  { zh: "自後元以來，祿去王室，政由冢宰。", literal: "Since the Houyuan era, emoluments have departed from the royal house and government has lain with the chief steward.", idiomatic: "Since the Houyuan era, emoluments have departed from the royal house and government has lain with the chief steward." },
  { zh: "今光死，子復為右將軍，兄子秉樞機，昆弟、諸婿據權勢，在兵官，光夫人顯及諸女皆通籍長信宮，或夜詔門出入，驕奢放縱，恐寢不制，宜有以損奪其權，破散陰謀，以固萬世之基，全功臣之世。", literal: "Now Guang is dead, his son again is Right General, his elder brother's son holds the pivot of power, brothers and sons-in-law hold authority in military offices, Guang's wife Xian and all daughters have registry at Changxin Palace, some enter and leave by night edict gates in arrogant extravagance and unbridled license—I fear they will not be controlled in sleep; there should be means to diminish and seize their power, break up secret plots, to secure the foundation of ten thousand generations and preserve the generations of meritorious ministers.", idiomatic: "Now Guang is dead, his son again is right general, his elder brother's son holds the pivot of power, brothers and sons-in-law hold authority in military offices, Guang's wife Xian and all daughters have registry at Changxin Palace, some enter and leave by night edict gates in arrogant extravagance—I fear they will not be controlled; means should be found to diminish their power, break up secret plots, secure the foundation of ten thousand generations, and preserve the generations of meritorious ministers." },
  { zh: "」又故事：諸上書者皆為二封，署其一曰「副」，領尚書者先發副封，所言不善，屏去不奏。", literal: "\" Moreover by precedent: all who memorialized made two seals, marking one \"duplicate\"; whoever oversaw the Secretariat first opened the duplicate seal—if the words were not good, it was set aside and not presented.", idiomatic: "\" Moreover by precedent: all memorialists made two seals, marking one \"duplicate\"; whoever oversaw the secretariat first opened the duplicate seal—if the words were unfavorable, it was set aside and not presented." },
  { zh: "相復因許伯白去副封以防壅蔽。", literal: "Xiang again through Lord Xu reported asking to remove the duplicate seal to guard against obstruction and concealment.", idiomatic: "Xiang again through Lord Xu reported asking to remove the duplicate seal to guard against obstruction." },
  { zh: "帝善之，詔相給事中，皆從其議。", literal: "The emperor approved; an edict made Xiang Attendant Within the Gates; all followed his proposals.", idiomatic: "The emperor approved; an edict made Xiang attendant within the gates; all followed his proposals." },
  { zh: "----4帝興於閭閻，知民事之艱難。", literal: "----4 The emperor rose from lanes and alleys and knew the hardship of the people's affairs.", idiomatic: "----4 The emperor rose from common lanes and knew the hardship of the people's affairs." },
  { zh: "霍光既薨，始親政事，厲精為治，五日一聽事。", literal: "Once Huo Guang had died, he began personally to handle government, striving in spirit to govern, hearing affairs every five days.", idiomatic: "Once Huo Guang had died, he began personally to handle government, striving in spirit to govern, hearing affairs every five days." },
  { zh: "自丞相以下各奉職奏事，敷奏其言，考試功能。", literal: "From the Chancellor down, each performed his office and presented affairs; he spread forth their words and examined and tested their function.", idiomatic: "From the chancellor down, each performed his office and presented affairs; he spread forth their words and examined their performance." },
  { zh: "侍中、尚書功勞當遷及有異善，厚加賞賜，至於子孫，終不改易。", literal: "Attendants within and Secretariat officials whose merit warranted promotion or who had unusual goodness received rich rewards extending to their sons and grandsons, never altered.", idiomatic: "Attendants within and secretariat officials whose merit warranted promotion or who had unusual excellence received rich rewards extending to their sons and grandsons, never altered." },
  { zh: "樞機周密，品式備具，上下相安，莫有苟且之意。", literal: "The pivot of power was close and thorough; grades and models were fully provided; above and below were at peace, and none had a perfunctory mind.", idiomatic: "The pivot of power was close and thorough; grades and models were fully provided; above and below were at peace, and none were perfunctory." },
  { zh: "及拜刺史、守、相，輒親見問，觀其所由，退而考察所行以質其言，有名實不相應，必知其所必然。", literal: "When appointing governors, prefects, and chancellors of states, he immediately personally received them and questioned them, observing their origins; afterward he examined their conduct to verify their words—if name and reality did not correspond, he was sure to know what would necessarily follow.", idiomatic: "When appointing governors, prefects, and chancellors of states, he immediately personally received and questioned them, observing their origins; afterward he examined their conduct to verify their words—if name and reality did not correspond, he was sure to know what would follow." },
  { zh: "常稱曰：「庶民所以安其-{田里}-而亡歎息愁恨之心者，政平訟理也。", literal: "He often said: \"The reason the common people can settle their -{田里}- and be without sighing and resentful hearts is that government is level and lawsuits are settled.", idiomatic: "He often said, \"The reason the common people can settle their -{田里}- and be without sighing and resentful hearts is that government is level and lawsuits are settled." },
  { zh: "與我共此者，其唯良二千石乎！", literal: "Those who share this with me—are they not the good two-thousand-bushel officials!", idiomatic: "Those who share this with me—are they not the good two-thousand-bushel officials!" },
  { zh: "」以為太守，吏民之本，數變易則下不安；", literal: "\" He held that the governor is the root of clerks and people; frequent changes make those below unsettled;", idiomatic: "\" He held that the governor is the root of clerks and people; frequent changes make those below unsettled;" },
  { zh: "民知其將久，不可欺罔，乃服從其教化。", literal: "when the people know he will be long in office and cannot be deceived, then they submit to his transforming instruction.", idiomatic: "when the people know he will be long in office and cannot be deceived, then they submit to his transforming instruction." },
  { zh: "故二千石有治理效，輒以璽書勉厲，增秩，賜金，或爵至關內侯；", literal: "Therefore when a two-thousand-bushel official had governing effect, he immediately sent a seal-letter to encourage and urge him, increased his rank, bestowed gold, or ennobled him to Marquis Within the Passes;", idiomatic: "Therefore when a two-thousand-bushel official had governing effect, he immediately sent a seal-letter to encourage him, increased his rank, bestowed gold, or ennobled him to marquis within the passes;" },
  { zh: "公卿缺，則選諸所表，以次用之。", literal: "when a high minister's office was vacant, he selected from those recommended, using them in order.", idiomatic: "when a high minister's office was vacant, he selected from those recommended, using them in order." },
  { zh: "是以漢世良吏，於是為盛，稱中興焉。", literal: "Thus in the Han age good officials were then at their flourishing, and it was called the Restoration.", idiomatic: "Thus in the Han age good officials flourished as never before, and the era was called the Restoration." },
  { zh: "----5匈奴壺衍鞮單于死，弟左賢王立為虛閭權渠單于，以右大將女為大閼氏，而黜前單于所幸顓渠閼氏。", literal: "----5 Chanyu Huyandi of the Xiongnu died; his younger brother the Left Wise King was established as Chanyu Xulüquanqu, took the Right Grand General's daughter as great yanzhi, and dismissed the former chanyu's favored Zhuanqu yanzhi.", idiomatic: "----5 Chanyu Huyandi of the Xiongnu died; his younger brother the Left Wise King became Chanyu Xulüquanqu, made the Right Grand General's daughter chief queen, and demoted the former chanyu's favored Zhuanqu." },
  { zh: "顓渠閼氏父左大且渠怨望。", literal: "Zhuanqu yanzhi's father, the Left Grand Daqu, bore resentment.", idiomatic: "Zhuanqu's father, the Left Grand Daqu, nursed a grudge." },
  { zh: "是時漢以匈奴不能為邊寇，罷塞外諸城以休百姓。", literal: "At this time Han, because the Xiongnu could not raid the borders, abolished the various cities beyond the passes to rest the common people.", idiomatic: "At this time Han, seeing the Xiongnu could not raid the borders, dismantled outpost cities beyond the passes to spare the people." },
  { zh: "單于聞之，喜，召貴人謀，欲與漢和親。", literal: "The chanyu heard it and was pleased; he summoned nobles to deliberate and wished to make peace kinship with Han.", idiomatic: "The chanyu rejoiced, summoned his nobles to counsel, and wished to seek peace kinship with Han." },
  { zh: "左大且渠心害其事，曰：「前漢使來，兵隨其後。", literal: "The Left Grand Daqu inwardly resented the affair and said: \"Previously when Han envoys came, troops followed behind them.", idiomatic: "The Left Grand Daqu inwardly opposed the plan and said, \"Previously when Han envoys came, troops followed behind them." },
  { zh: "今亦效漢發兵，先使使者入。", literal: "Now too imitate Han in raising troops—first send envoys in.", idiomatic: "Now imitate Han: raise troops and send envoys in first." },
  { zh: "」乃自請與呼盧訾王各將萬騎，南旁塞獵，相逢俱入。", literal: "\" Thereupon he himself requested that he and King Hulüze each lead ten thousand horsemen south to hunt beside the barrier, meet, and enter together.", idiomatic: "\" He then volunteered that he and King Hulüze each lead ten thousand horsemen south to hunt along the border, meet up, and enter together." },
  { zh: "行未到，會三騎亡降漢，言匈奴欲為寇。", literal: "Before they had gone, it happened that three riders fled and surrendered to Han, saying the Xiongnu wished to raid.", idiomatic: "Before they arrived, three riders defected to Han and reported that the Xiongnu intended to raid." },
  { zh: "於是天子詔發邊騎屯要害處，使大將軍軍監治眾等四人將五千騎，分三隊，出塞各數百里，捕得虜各數十人而還。", literal: "Thereupon the Son of Heaven ordered border cavalry to encamp at critical points and sent four army supervisors of the Grand General such as Zhi Zhong, each leading five thousand horsemen in three columns beyond the passes several hundred li each, capturing several tens of captives each and returning.", idiomatic: "Thereupon the emperor ordered border cavalry to garrison chokepoints and sent four Grand General's army supervisors including Zhi Zhong, each with five thousand horsemen in three columns beyond the passes for several hundred li each, capturing several tens of captives apiece before returning." },
  { zh: "時匈奴亡其三騎，不敢入，即引去。", literal: "At that time the Xiongnu, having lost those three riders, did not dare enter and at once withdrew.", idiomatic: "The Xiongnu, missing those three riders, did not dare enter and at once withdrew." },
  { zh: "是歲，匈奴饑，人民、畜產死者什六七，又發兩屯各萬騎以備漢。", literal: "That year the Xiongnu suffered famine; of the people and livestock six or seven tenths died, and they also raised two encampments of ten thousand horsemen each to guard against Han.", idiomatic: "That year famine struck the Xiongnu; six or seven tenths of the people and livestock perished, and they still posted two camps of ten thousand horsemen each against Han." },
  { zh: "其秋，匈奴前所得西嗕居左地者，其君長以下數千人皆驅畜產行，與甌脫戰，所殺傷甚眾，遂南降漢。", literal: "That autumn those the Xiongnu had earlier taken from the Western Ruo dwelling in the left zone—from chiefs downward, several thousand in all—all drove livestock on the march, fought Ouduo, killed and wounded very many, and thereupon went south to surrender to Han.", idiomatic: "That autumn several thousand western captives the Xiongnu had held in the left zone—from chiefs downward—drove their herds forth, fought their Ouduo guards, inflicted heavy casualties, and defected south to Han." },
  { zh: "----category:資治通鑑", literal: "----category: Zizhi Tongjian", idiomatic: "----category: Zizhi Tongjian" }
];
